-- Generated by QuestData/Tools/import_multilanguage_quests.py.
-- Known IDs only; Classic-source passages are compatibility fallbacks on Forever.
local source = "MultiLanguage Classic c51dc2e5141f070f5b92de190521d79e8dccaeab"
local data = WordHunterWoW_QuestDataByFlavor
local function apply(id, targets, passages)
    for _, flavor in ipairs(targets) do
        local languages = data and data[flavor]
        for locale, fields in pairs(passages) do
            local record = languages and languages[locale] and languages[locale][id]
            if record then
                for field, text in pairs(fields) do
                    if not record[field] or record[field] == "" then
                        record[field] = text
                        record[field .. "Source"] = source
                        record[field .. "SourceFlavor"] = "classic"
                    end
                end
            end
        end
    end
end

apply(1650, { "classic", "forever" }, { deDE = { completion = "Hallo, {name}. Wenn ich Eure Rüstungen und Waffen sehe, denke ich, dass Ihr mir entweder mein Land wegnehmen wollt oder die Kirche endlich jemanden zu meinem Schutz geschickt hat, so lange Jordan fort ist.\n\nDarf ich mich Euch vorstellen: Ich bin Daphne Stilwell. Ist mir ein Vergnügen.\n\nUnd Ihr kommt nicht zu spät... Seit dem letzten Sonnenaufgang habe ich erst ein halbes Dutzend dieses Abschaums getötet. Sie brauchen eine Weile, bis sie um die Kurve gebogen sind, aber sie haben Euch vermutlich gesehen. Dies bedeutet, dass sie wahrscheinlich jede Minute hier sein werden." }, enUS = { completion = "Hello, {name}. I'm assuming by all that armor and weapon of yours, you're either here to try and take my land, or the Church finally sent someone to help protect me while my Jordan's gone.\n\nWell, let me introduce myself: I'm Daphne Stilwell. It's a pleasure.\n\nNow, you're not too late... I've only killed a half dozen of the scum since last sun up. They've been a little slow getting 'round the bend up there, but they probably saw you coming, which means they'll probably be here any minute." } })
apply(1651, { "classic", "forever" }, { deDE = { progress = "Wir werden unsere Position beim Haus beziehen!", completion = "Wir haben es geschafft, {name}! Danke für Eure Hilfe. Ihr wart wirklich erstaunlich da draußen. Ich hätte nie gedacht, dass es ein {class} mit so vielen Gegnern gleichzeitig aufnehmen kann.\n\nIhr habt wahrlich Tapferkeit im Angesicht einer Übermacht gezeigt." }, enUS = { progress = "We'll make our stand at the house!", completion = "We've done it, {name}! Thank you for your help. You were truly amazing out there. I never thought a {class} could handle so many enemies at once.\n\nYou've truly shown bravery in the face of overwhelming odds." } })
apply(1652, { "classic", "forever" }, { deDE = { completion = "So begegnen wir uns wieder, {name}, und wie ich sehe, seid Ihr bester Laune.\n\nDas Heim der Stilwells ist wieder einen Tag sicher, und Eurer Geschichte entnehme ich, dass es an Gefahren nicht gemangelt hat. Gut gemacht.\n\nDaphne und Jordan haben der Kirche sehr geholfen. Dass wir ihr Eigentum - und ihr Leben - durch Euch beschützen ließen, war das Geringste, was wir für sie tun konnten.\n\nIhr werdet für Euren Wagemut belohnt werden." }, enUS = { completion = "So, we meet again, {name}, and you are in high spirits, I see.\n\nThe Stilwell home will be safe for another day, and from your story I see that there was no shortage of danger to be found. Well done.\n\nDaphne and Jordan have helped the Church greatly, and having you protect their property--and their very lives--was the least we could do for them.\n\nFor your valor, you will be rewarded." } })
apply(1653, { "classic", "forever" }, { deDE = { completion = "Guten Tag, {name}. Das Licht ist mit Euch, nehme ich an?\n\nWie war das? Duthorian hat Euch geschickt!? Meine Frau, wie geht es ihr? Ich wusste, es würde Ärger geben, wenn ich fortgehe. Bitte sagt mir, dass sie... oh, welch ein Glück. Ich bin so froh, dass sie in Sicherheit ist. Die Defias waren lange vor diesen Angriffen eine Bedrohung, aber jetzt können es die Berater des Königs nicht mehr leugnen.\n\nWas hat Duthorian noch gesagt?\n\nIhr wart es, der meine Frau beschützt hat? Dann danke ich Euch nochmals, {name}. Eine bessere Prüfung der Ehre kann ich mir nicht vorstellen." }, enUS = { completion = "Good day, {name}. The Light is with you, I trust?\n\nWhat's that? You were sent by Duthorian!? My wife, how is she? I knew there was going to be trouble if I left. Please tell me she's... oh, thank goodness. I'm so glad that she's safe. The Defias were a threat long before these attacks, but now the King's advisors cannot deny it.\n\nWhat else did Duthorian have to say?\n\nYou're the one that was sent to protect my wife? Then I thank you again, {name}. I couldn't think of a better test of valor than that." } })
apply(1654, { "classic", "forever" }, { deDE = { progress = "Es dürfte schwer sein, die Gegenstände zu bekommen, die Ihr sucht, aber ich versichere Euch, die Waffe, die ich für Euch anfertige, rechtfertigt den Aufwand.\n\nSie wird meine bis dato beste Arbeit werden, und doch nur ein geringer Lohn für den Dienst, den Ihr mir erwiesen habt.", completion = "Das ist wunderbar! Ihr habt alle Gegenstände bekommen.\n\nDamit müsste ich Euch problemlos eine grandiose Waffe schmieden können. Ích hatte seit langem Pläne dafür, aber bisher nie Gelegenheit gefunden, die Zutaten herbeizuschaffen. Danke, {name}.\n\nEs tut gut, wieder den Hammer meines Vaters zu schwingen... und einen Edelstein aus Kor, ich dachte nicht, dass ich je selbst einen sehen würde." }, enUS = { progress = "The items you're seeking will be difficult to acquire, but I can assure you, the weapon I will craft for you will be worth the effort.\n\nIt will be my finest work to date, and only a small payment for the service you've done me.", completion = "This is wonderful! You've gotten all the items.\n\nI should have no problem forging you a grand weapon with these. I've actually had the plans for doing this for some time, I just never had the opportunity to gather the goods. Thank you, {name}.\n\nIt feels good to have my father's hammer again... and a Kor gem, I never thought I'd see one of these myself." } })
apply(1656, { "classic", "forever" }, { deDE = { progress = "Ja, Kindchen? Was kann Kauth für Euch tun?\n\nDie Reise von der Mesa hierher kann für manche eine enorme Last, aber für andere eine willkommene Abwechslung sein. Was ist sie wohl für Euch, frage ich mich...", completion = "Ah, die Felle, auf die ich gewartet habe! Danke.\n\nSie kamen schneller als ich erwartet hatte. Ich mache gute Decken für meine Logiergäste daraus.\n\nIhr könnt gern bleiben, so lange Ihr möchtet. Mein Gasthaus ist stets offen und alle Eures Volkes sind willkommen. Und unterschätzt eine angenehme Nachtruhe nicht, ihr kann auf Reisen eine große Bedeutung zukommen." }, enUS = { progress = "Yes, young one? What can Kauth do for you?\n\nThe journey here from the Mesa can be a tremendous burden for some, but a welcome sight for others. Which is it for you, I wonder?", completion = "Ah, the furs I was expecting. Thank you.\n\nThese came faster than I had expected. They will make good blankets for anyone who wishes to stay here.\n\nPlease feel free to stay as long as you like. My inn is always open and all of our people are welcome here. And don't underestimate a good night's rest, it can make a great difference while you're out traveling." } })
apply(1657, { "classic", "forever" }, { deDE = { completion = "Ah, gut gemacht! Ich hoffe die Allianz erstickt an dem fauligen Gift, das wir ihnen verabreicht haben, genauso wie wir den Witz der Versklavung an die Geißel schlucken mussten!\n\nIhr habt die wahre Bedeutung der Schlotternächte erhalten, {name}, ich danke Euch dafür. Lasst mich ein paar Schlotternachtssüßigkeiten mit Euch als zusätzliche Belohung teilen. Ihr werdet sie sicher als eine recht angenehme Abwechslung betrachten!" }, enUS = { completion = "Ah, well done!  I hope the Alliance chokes on the foul gift we've given them, much like we were forced to choke on the yoke of enslavement to the Scourge!\n\nYou've kept the ideas of Hallow's End true, {name}, and for that I salute you.  As an extra bonus, let me share some of these Hallow's End treats I have with you.  I think you might find them to be quite the enjoyable diversion!" } })
apply(1658, { "classic", "forever" }, { deDE = { completion = "Gut gemacht, {name}. Das Fest des Weidenmanns wird auch noch zukünftig für Ärger sorgen, wenn die abscheulichen Verlassenen weiterhin die Verbliebenen von Lordaeron jagen dürfen. Es ist KEINE passende Ehrung für dieses einst so stolze Königreich, lasst Euch das gesagt sein...\n\nHier sind ein paar Münzen für eventuell benötigte Reparaturen. Ich habe dem Anlass entsprechend auch ein paar Süßigkeiten, die Ihr mögen könntet, mit hinzugepackt. Gruselige Schlotternächte - lasst es uns dafür sorgen, dass es in Southshore so sicher wie möglich bleibt." }, enUS = { completion = "Well done, {name}.  The Wickerman Festival will continue to be trouble so long as the abominable Forsaken are allowed to haunt the remnants of Lordaeron.  It is NOT a fitting tribute to that once proud kingdom, let me tell you...\n\nHere's some coin for any repairs you might need, and in the spirit of the season I've also included some treats you might like.  Happy Hallow's End - let's keep it as safe as possible here in Southshore." } })
apply(1665, { "classic", "forever" }, { deDE = { progress = "Ich habe Euch mit Bartleby kämpfen gesehen. Ordentlich gemacht! Habt Ihr seinen Becher?", completion = "Da ist er! Er wollte ihn nicht hergeben, aber Ihr wart sehr überzeugend. Gut gemacht.\n\nNun zu Eurer Lektion..." }, enUS = { progress = "I saw your fight with Bartleby.  Nicely done!  Did you get his mug?", completion = "There it is!  He sure didn't want to part with it, but you were persuasive.  Well done.\n\nNow for your lesson..." } })
apply(1666, { "classic", "forever" }, { deDE = { completion = "Wer ist das? Burlguard, seid Ihr das? Ihr müsst etwas näher kommen. Meine Augen sind nicht mehr das, was sie einst waren. Euch so anzuschleichen, ich dachte schon, Ihr wärt ein Gnoll!" }, enUS = { completion = "Who's that?  Burlguard, is that you?  You'll have to step a little closer.  My eyes aren't what they used to be.  Walking up like that, I thought you were a gnoll!" } })
apply(1667, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meinen Stern? Ich will mir gar nicht vorstellen, welche Unbill Stumpfzahn Jack damit hätte anstellen können.", completion = "Prima, Ihr habt ihn! Ich fürchtete, er sei für immer dahin und würde von den Defias benutzt werden, um sich als Beamte von Stormwind ausgeben zu können. Dank Euch wird es dazu jetzt nicht kommen.\n\nHier einige Waffen, die ich benutzt habe, als ich noch Marshal war. Ich habe sie gut in Schuss gehalten - trefft Eure Wahl!" }, enUS = { progress = "Do you have my badge? I don't want to think of the mischief Dead-tooth Jack could cause with it.", completion = "Great, you found it!  I feared it was gone forever, used by the Defias to impersonate a Stormwind official.  Well that won't happen now, thanks to you.\n\nHere are some weapons I used when I was a Marshal.  I kept them in great shape--take your pick!" } })
apply(1678, { "classic", "forever" }, { deDE = { progress = "Seid Ihr in Vejreks Hütte gewesen, {name}? Rieche ich Trollgestank an Euch?", completion = "Vejrek war ein hässlicher Kerl, was? Ordentlich gemacht, {name}! Ihr habt eindeutig das Zeug dazu, also fangen wir mit der Lektion an...\n\nIhr wisst es vielleicht nicht, aber eine starke Verteidigung ist sehr wichtig für einen {class}. Damit besteht er noch gegen Feinde, wenn andere schon niedergeschmettert wären, und genau so einen brauchen Eure Verbündeten." }, enUS = { progress = "Have you been to Vejrek's hut, {name}?  Is that troll stink I smell on you?", completion = "Vejrek sure was an ugly one, eh?  Nicely done, {name}!  You have what it takes, now let's start your lesson...\n\nYou may not know it, but a strong defense is very important to a {class}.  It keeps him standing against foes that'd fell others, and that's what your allies need." } })
apply(1679, { "classic", "forever" }, { deDE = { completion = "Ah, {name}. Ich hörte, wie die {class} von Dun Morogh Euren Namen erwähnten. Ich hoffe, Ihr habt nicht Eure ganze Zeit in den Brauereien verbracht!" }, enUS = { completion = "Ah, {name}.  I heard the warriors of Dun Morogh bouncing your name around.  I hope you haven't spent all your time in the breweries!" } })
apply(1680, { "classic", "forever" }, { deDE = { completion = "Muren hat Euch geschickt, nicht? Ja, ich kann Euch eine hübsche Waffe machen... aber vorher muss ich Euch um einen Gefallen bitten.\n\nSeid unbesorgt. Es ist ziemlich gefährlich und könnte Euren Tod bedeuten; also genau das, was ein {class} sich wünscht." }, enUS = { completion = "Muren sent you, did he?  Yes, I can make you a nice weapon... but before I do that, I have a favor to ask of you.\n\nDon't worry.  It's plenty dangerous and could mean your death; it's exactly the sort of job a {class} wants." } })
apply(1681, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Ironbands Areal betreten? Und habt Ihr das Umbralerz gefunden?", completion = "Ihr habt es gefunden! Gut gemacht!\n\nIch hoffe, Ihr habt im Lauf der Suche eine Menge Dunkeleisenzwerge getötet. Ich fürchte, wir werden sie auf Ironbands Areal nicht zum letzten Mal gesehen haben.\n\nAber danke für das Erz, {name}. Ich brenne darauf, seine Eigenschaften herauszufinden." }, enUS = { progress = "Have you entered Ironband's Compound?  Did you find the umbral ore?", completion = "You found it! Well done!\n\nI hope you killed a host of Dark Iron dwarves while searching.  I fear that Ironband's compound won't be the last place we see them.\n\nBut thank you for the ore, {name}.  I'm eager to work it and find its properties." } })
apply(1683, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Horn, {name}. Ist unser Mondbrunnen von dem Scheusal Vorlus befreit?", completion = "Gut gemacht, {name}. Gut zu wissen, dass Vorlus besiegt und unser Mondbrunnen gesäubert ist, und schön zu sehen, dass junge {class} erpicht sind, unser geliebtes Teldrassil frei von Verderbnis zu halten.\n\nBeginnen wir jetzt Eure Ausbildung..." }, enUS = { progress = "Do you have the horn, {name}?  Is our moonwell free of the fiend Vorlus?", completion = "Well done, {name}.  It is good to know Vorlus is defeated and our moonwell cleansed, and it is good to see young warriors eager to keep our beloved Teldrassil free of corruption.\n\nNow let us begin your training..." } })
apply(1684, { "classic", "forever" }, { deDE = { completion = "Ich entbiete Euch einen Gruß, {name}. Man hört Euren Namen oft in Darnassus, denn Ihr seid viel versprechend. Doch wir werden sehen, ob Ihr die Willenskraft besitzt, dem Pfad des Kriegers zu folgen." }, enUS = { completion = "I bid you greetings, {name}.  Your name rings loudly in Darnassus, for you show promise.  But we shall soon see if you possess the strength of will to follow the path of the {class}." } })
apply(1685, { "classic", "forever" }, { deDE = { completion = "Höchste Zeit, dass Ihr erscheint. Ich hätte vielleicht einen Tüchtigeren als Remen auf die Suche nach Euch schicken sollen.\n\nEinerlei.\n\nIhr wart zu lange ohne Ausbildung, und ein {class} ohne Ausbildung behält den Kopf nicht lange auf den Schultern." }, enUS = { completion = "About time you showed up. Though, perhaps I should have sent someone more capable than Remen to find you.\n\nNo matter.\n\nYou've gone too long without training, and a {class} without training isn't like to keep his head on his shoulders for long." } })
apply(1686, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Eluras Schemen besiegt, {name}? Und habt Ihr das verlorene Eluniterz?", completion = "Tapfer, tapfer, {name}.\n\nIhr habt Eluras Schemen den wohlverdienten Frieden gegeben. Aus dem gewonnenen Elunit werden wir eine prima Waffe für Euch machen." }, enUS = { progress = "Have you defeated the Shade of Elura, {name}?  And do you have the lost elunite ore?", completion = "Bravely done, {name}.\n\nYou have given the Shade of Elura much deserved peace, and we will use the gathered elunite to make a fine weapon for you." } })
apply(1688, { "classic", "forever" }, { deDE = { progress = "Selbst die Alten und Weisen können sich von Jugend und Schönheit blenden lassen, {name}. Ihr tätet gut daran, diesen Rat Euer ganzes Leben lang nicht zu vergessen.", completion = "Surena war begabt, aber nicht so sehr, dass sie die Hexenmeistermagie selbst gemeistert hätte. Ein Jammer, dass ein Talent verschwendet wird, aber manchmal geht es nicht anders.\n\nIch hoffe, meine Investition in Euch wird andere Resultate zeigen." }, enUS = { progress = "Even the older and wiser can be unmanned by the wiles of youth and beauty, {name}. A piece of advice you would do well to remember throughout your life.", completion = "Surena was talented, but not enough so to gain mastery of {class} magic on her own. It's a shame to see talent wasted, but sometimes it is necessary.\n\nI hope my investment in you will bear different results." } })
apply(1689, { "classic", "forever" }, { deDE = { progress = "Ich kann Euch erst zeigen, wie man einen Leerwandler kontrolliert, wenn Ihr einen beschworen habt.", completion = "Ihr habt Eure Sache besser als erwartet gemacht, {name}, aber so gut, wie ich gehofft hatte. Jetzt könnt Ihr lernen, wie Ihr Euren unterworfenen Leerwandler beherrscht, einen Verbündeten, der Euch in den bevorstehenden Prüfungen sicher höchst nützlich ist.\n\nIm Augenblick kann ich Euch nichts mehr beibringen, bin aber noch lange nicht fertig mit Euch, {name}." }, enUS = { progress = "I cannot show you how to control a voidwalker until you have overtaken one.", completion = "You did better than I expected, {name}, but as well as I'd hoped. Now, you can learn to command your subjugated voidwalker, an ally you will find valuable in the trials that are sure to stand before you.\n\nI have nothing more to teach you at the present, but I am far from done with you, {name}." } })
apply(1690, { "classic", "forever" }, { deDE = { completion = "Tja, das nenne ich Effizienz! Ihr habt uns geholfen, die Nomaden so weit zu dezimieren, dass wir uns jetzt überlegen können, wie wir die Wasserbrunnen zurückerobern.\n\nDie Gadgetzan Water Company dankt Euch für Eure Hilfe, aber wir sind mit diesen stinkenden Nomaden noch lange nicht fertig. Hört gut zu - das benötigen wir als Nächstes ..." }, enUS = { completion = "Now that's what I call efficiency!  You've helped thin out the nomad's numbers enough now that we can start to think about how we can win back those water wells.\n\nThe Gadgetzan Water Company thanks you for your help, but we're far from done in dealing with those foul nomads.  Listen close - here's what we need next..." } })
apply(1691, { "classic", "forever" }, { deDE = { progress = "Na, konntet Ihr diese Nomaden ausschalten, wie ich Euch gebeten hatte? Die Gadgetzan Water Company entwickelt Pläne, die auf Eurem Erfolg hier basieren! Lasst uns jetzt nicht im Stich...", completion = "Erstklassige Arbeit, {name}... erstklassig! Ihr habt die Nomadenbevölkerung so weit dezimiert, dass wir tatsächlich den Kampf gegen sie aufnehmen können!\n\nFalls Ihr es noch nicht getan habt, dann sprecht mit Leitungshahnmaschinist Luglunket hier; er vergibt ein Kopfgeld für jeden Wasserbeutel eines Wüstenläufers, über den Ihr gestolpert seid, während Ihr diese Nomaden der Gerechtigkeit zugeführt habt!" }, enUS = { progress = "Well, were you able to take out those nomads like I asked?  The Gadgetzan Water Company is developing plans based on your success here!  Don't let us down, now...", completion = "Top notch work, {name}... top notch!  You've thinned down the nomad population to a point where we can actually take the fight to them!\n\nIf you haven't already, talk to Spigot Operator Luglunket here; he gives a bounty on any of the Wastewander water pouches you may have run across while bringing those nomads to justice!" } })
apply(1692, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, junger {class}. Wie kann ich Euch mit meinen Fertigkeiten dienlich sein?", completion = "Ah, Eluniterz. Ein Metall, mit dem sich gut arbeiten lässt, denn es wurde von der Göttin Elune persönlich gesegnet. Es wäre mir eine Ehre, Waffen daraus herzustellen.\n\nBitte wartet, während ich arbeite..." }, enUS = { progress = "Greetings, young {class}.  How might my skills serve you?", completion = "Ah, elunite ore.  This is a fine metal to work with, for it is blessed by the goddess Elune herself.  It would be an honor to craft weapons with it.\n\nPlease wait while I work..." } })
apply(1698, { "classic", "forever" }, { deDE = { completion = "Ha! Ihr habt von meiner Herausforderung gehört, richtig?\n\nSetzt Euch und hört zu. Bestellt ein Getränk und genießt es... es könnte Euer Letztes sein." }, enUS = { completion = "Hah!  So you heard of my challenge, did you?\n\nWell sit down and listen.  Have a drink, and savor it... because it might be your last." } })
apply(1699, { "classic", "forever" }, { deDE = { completion = "Ihr habt es geschafft! Gut gemacht! Ein dreifach Hoch für {name}!" }, enUS = { completion = "You made it!  Well done!  Three cheers for {name}!" } })
apply(1700, { "classic", "forever" }, { deDE = { progress = "Hallo und schönen Tag. Wie kann ich Euch dienlich sein?", completion = "Furen hat das geschrieben? Wie kann er es wagen! Ich habe ihm all das beigebracht, was er weiß! Unerhört, dass er glaubt, er könnte mich etwas lehren! Unerhört!\n\nHm... aber in diesen Notizen steht etwas, das ich gern versuchen würde..." }, enUS = { progress = "Hello, and well met.  How might I be of service to you?", completion = "Furen wrote this?  How dare he!  Why, I taught him everything he knows!  To think he could teach me something is outrageous!  Outrageous!\n\nHm... but there is something in his notes that I'd like to try..." } })
apply(1701, { "classic", "forever" }, { deDE = { progress = "Wie läuft die Suche, {name}? Habt Ihr die Materialien?", completion = "Ihr habt alles? Erstaunlich! Ich hatte befürchtet, diese Schimären würden Euch fressen!\n\nDann lasst uns mal mit der Rüstung anfangen..." }, enUS = { progress = "How goes the scavenger hunt, {name}?  Do you have the materials?", completion = "You got it all?  Amazing!  I was afraid those chimaeras would eat you up for sure!\n\nWell let's get started on that armor..." } })
apply(1702, { "classic", "forever" }, { deDE = { progress = "Hallo! Trockene Zeiten, findet Ihr nicht auch?", completion = "Ah, Gerstenbräu. Erstklassiges Gesöff! Ihr seid also bei Yorus gewesen, hm?\n\nIch kann Euch einen Schild machen, ja Sir! Einen Besseren werdet Ihr nicht finden, ungelogen!" }, enUS = { progress = "Hello!  Dry times, don't you think?", completion = "Ah, Barleybrew Scalder.  Great stuff!  So you've been to see Yorus, eh?\n\nI can get you a shield, yes sir!  You won't find a better one, and that's no lying!" } })
apply(1703, { "classic", "forever" }, { deDE = { progress = "Ich entbiete Euch einen Gruß, {class}.", completion = "Das ist interessant, wirklich sehr interessant. Mein Zwergen-Kollege Furen hat da eine grandiose Entdeckung gemacht!\n\nDanke, {name}. Es wäre mir eine Ehre, seine neuen Techniken selbst anzuwenden." }, enUS = { progress = "I bid you greetings, {class}.", completion = "These are interesting, very interesting indeed.  My dwarven colleague Furen has made quite a grand discovery!\n\nThank you, {name}.  It will be an honor to apply his new techniques to my own craftings." } })
apply(1704, { "classic", "forever" }, { deDE = { progress = "Guten Tag, Morgen oder Abend. Ich kann es von hier unten nicht erkennen. Bringt Ihr mir Arbeit?", completion = "Oh je! Diese Notizen sind erstaunlich! Und mehr noch... sie sind unglaublich und phantastisch und machen meine Knie ganz weich!\n\nFuren hatte einen Durchbruch! Einen echten Durchbruch! Ich kann es kaum erwarten, seine neue Technik zu erproben!" }, enUS = { progress = "Good day, or morning or evening.  I can't tell from way down here.  So do you have business for me?", completion = "Oh my!  These notes are amazing!  And what's more... they're incredible and they're stupendous and they make my knees go all a-wobbly!\n\nFuren had a breakthrough!  A real breakthrough!  I can't wait to try out his new technique!" } })
apply(1705, { "classic", "forever" }, { deDE = { progress = "{name}, habt Ihr das brennende Blut und den Fels? Ich brauche sie, um die Rüstung zu vollenden.", completion = "Saubere Arbeit! Wenn Ihr mich jetzt entschuldigen wollt, ich habe zu tun..." }, enUS = { progress = "{name}, do you have the burning blood and rock?  I'll need them to complete the armor.", completion = "Nice work!  Now if you'll excuse me, I have some work to do myself..." } })
apply(1707, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die fünf Wasserbeutel eines Wüstenläufers, die wir benötigen? Falls Ihr sie habt, dann gehört das Gadgetzan Water Company-Care-Paket, Modell 103-XB, Euch!", completion = "Hervorragend - je mehr Wasserbeutel wir wiederbeschaffen können, desto weiter sind wir von einer Katastrophe entfernt! Bringt mir mehr und ich werde Euch für jeweils fünf Wasserbeutel belohnen, die Ihr mir bringt." }, enUS = { progress = "Got the five Wastewander water pouches we need?  If you do, then the Gadgetzan Water Company Care Package, Model 103-XB, will be yours!", completion = "Excellent - the more water pouches we are able to reclaim, the further away from disaster we'll all be!  Keep 'em coming, and I will be sure to reward you for every five water pouches you bring me." } })
apply(1708, { "classic", "forever" }, { deDE = { progress = "Hallo, hallo, {name}. Habt Ihr die Sengkoralle? Ich will endlich arbeiten!", completion = "Das sind sie. Gut gemacht! Und jetzt lasst mich dies verhütten und zerhämmern, damit ich Furens Technik selbst anwenden kann. Mal sehen, was dann passiert!\n\nOh je, oh je! Ich weiß genau, diese Rüstung wird sehr, sehr hart!" }, enUS = { progress = "Hello hello, {name}!  Do you have the searing coral?  I can't wait to get to work!", completion = "That's the stuff!  Well done!  Now let me get this smelted and hammered so I can apply Furen's technique with my own and then we can see what happens!\n\nOh my, oh my!  I just know the armor will be very very very tough!" } })
apply(1710, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schalen, {name}? Sie sind recht stark und können zu einem Lack verarbeitet werden, mit dem ich die Kettenglieder meiner neuen Panzerrüstung überziehe.", completion = "Ah, danke. Dies wird großartig funktionieren!\n\nIch werde sofort mit der Rüstung beginnen..." }, enUS = { progress = "Do you have the shells, {name}?  They are quite strong, and can be rendered into a lacquer I will use to coat the links of my new mail armor.", completion = "Ah, thank you.  These will work splendidly!\n\nI will begin fashioning the armor immediately..." } })
apply(1712, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Gegenstände, {name}? Wenn Ihr sie sammelt, habe ich den Beweis, dass Ihr genügend Kraft besitzt, um es mit Cyclonian aufzunehmen.", completion = "Ihr habt die Gegenstände für meinen Zauber gesammelt und mir Eure Kraft und Geschicklichkeit bewiesen. Doch das nächste Stadium Eurer Aufgabe ist noch gefährlicher.\n\nHoffen wir, dass Eure Kraft nicht nachlässt." }, enUS = { progress = "Do you have the items, {name}?  Gathering them is the proof I need that you have the strength to face Cyclonian.", completion = "You have gathered the items for my spell, and have shown me your strength and cunning.  But the next stage of our quest is even more perilous.\n\nLet us hope your strength does not falter." } })
apply(1713, { "classic", "forever" }, { deDE = { progress = "{name}, ich muss das Wirbelherz haben!", completion = "Ihr habt es geschafft! Ihr habt Cyclonian besiegt und das Wirbelherz bekommen!" }, enUS = { progress = "{name}, I must have the whirlwind heart!", completion = "You did it!  You defeated Cyclonian and gained the Whirlwind Heart!" } })
apply(1715, { "classic", "forever" }, { deDE = { completion = "Blackwrench schickt Euch, richtig? Die verdammten {class} in Ironforge sollten mal ihre Köpfe benutzen. Der Platz und die Lehrer in Stormwind sind begrenzt. Durch den ständigen Zustrom werden wir früher oder später Aufmerksamkeit erregen." }, enUS = { completion = "Sent by Blackwrench, were you? Damn warlocks in Ironforge need to get things sorted out. There's only so much room and so many teachers in Stormwind. With all the increased traffic, we're sure to attract attention sooner or later." } })
apply(1717, { "classic", "forever" }, { deDE = { completion = "Ich bin froh, dass jemand Eurer habhaft wurde, {name}. Ich fürchtete schon das Schlimmste. Nach der vielen Zeit, die wir in Euch investiert haben, wäre es ein Jammer, Euch zu verlieren.\n\nAber wir können später reden. Wichtig ist jetzt nur Eure Ausbildung." }, enUS = { completion = "I'm glad someone was able to get a hold of you, {name}. I was beginning to fear the worst. It would be a shame to lose you, after the time we've invested in you.\n\nWe can talk later, though. Your training is the only important thing now." } })
apply(1718, { "classic", "forever" }, { deDE = { completion = "Hallo, {class}. Schön, dass Ihr auf das Prügel-Eiland gekommen seid. Hoffentlich gefällt es Euch hier..." }, enUS = { completion = "Hello, {class}.  It's good to see you made it to Fray Island.  I hope you find it to your liking..." } })
apply(1719, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Herausforderung absolviert?", completion = "Gut gemacht, {name}. Ihr habt den Ringkampf bestanden!\n\nIhr seid ein würdiger {class}. Es ist mir eine Ehre, Euch zu unterrichten..." }, enUS = { progress = "Have you completed your challenge?", completion = "Well done, {name}.  You have passed The Affray!\n\nYou are a worthy {class}, and I am honored to teach you..." } })
apply(1738, { "classic", "forever" }, { deDE = { progress = "War Eure Suche erfolgreich, {name}?", completion = "Ja, ich sehe, dass das voll und ganz genügt, lasst mich nur einen Moment damit arbeiten...\n\nTakar ist ein recht findiger Bursche, nicht? Wenn ich ihn nur überreden könnte, wieder in die Zivilisation zu kommen." }, enUS = { progress = "Was your search a success, {name}?", completion = "Yes, I can tell this will do nicely, let me just work with it for a moment...\n\nTakar is a resourceful fellow to have around, isn't he? If only I could persuade him to move back to civilization." } })
apply(1739, { "classic", "forever" }, { deDE = { progress = "Manchmal frage ich mich, ob Surena nicht ein verkleideter Sukkubus war, der geschickt wurde, um meinen Geist zu verwirren... Ha! Ich glaube, ich überschätze sie doch ein bisschen...", completion = "Gut gemacht, gut gemacht, {name}. Wie ich sehe, haben wir gut daran getan, Euch auszubilden. Eure Leistung enttäuschte uns nicht...\n\nIch habe keine Bedenken, Euch zu zeigen, wie Ihr Euren neu gebundenen Sukkubus kontrollieren könnt. Passt gut auf." }, enUS = { progress = "Sometimes I wonder if Surena was not a succubus in disguise, sent to warp and twist my mind... Ha! I give her too much credit, I think.", completion = "Well done, well done, {name}. I see we've done right in deciding to train you. Your performance certainly does not disappoint.\n\nI've no qualms in showing you the way to control your newly bound succubus. Observe carefully." } })
apply(1778, { "classic", "forever" }, { deDE = { completion = "Ihr seid also so schnell wieder hier, hm? Und was, sagt an, habt Ihr in der Zeit, die Ihr in der Ferne verbrachtet, denn erreicht?\n\nKonntet Ihr bei einem edlen Unterfangen helfen? Vielleicht habt Ihr den Wert der Barmherzigkeit gelernt, oder etwas mehr über Eure Verpflichtung gegenüber den Bürgern von Azeroth erfahren. Sagt mir, wem Ihr geholfen habt, und wie... Beeindruckend, {name}, das sind gewiss Taten von einem, der dem Licht folgt.\n\nSolche Opfer werden im Laufe der Zeit immer belohnt." }, enUS = { completion = "So, you've returned so quickly, huh? And what pray tell have you accomplished in your time away from here?\n\nWere you able to help a noble cause? Perhaps you've learned the value of charity or some more about your obligations to the citizens of Azeroth. Tell me, who have you helped and how.... Impressive, {name}, those are surely the actions of one who follows the Light.\n\nSuch sacrifice will always be rewarded in time." } })
apply(1783, { "classic", "forever" }, { deDE = { completion = "Ich kann Euch nicht genug danken, Bruder.\n\nDa Ihr das Symbol des Lebens tragt, kann ich nur vermuten, dass Tiza und Muiredon Euch hergeschickt haben.\n\nEs stimmt, ich wurde Opfer der Dunkeleisenzwerge, als ich versuchte, eines der Manuskripte zu bekommen: Es gelang mir so lange durchzuhalten, bis Muiredon entkommen konnte, aber das Licht hätte mich fast in sich aufgenommen, als Ihr gekommen seid. Dass Ihr mächtig genug wart, das Symbol zu benutzen, bedeutet eine große Zukunft für Euch, doch davon wollen wir später sprechen." }, enUS = { completion = "I can't thank you enough, brother.\n\nI can only assume that Tiza and Muiredon sent you here to aid me if you carry the Symbol of Life.\n\nIt's true, I fell to the Dark Iron while trying to attain one of the scripts: I was able to hold on long enough to allow Muiredon to escape, but the Light had almost embraced me fully when you came along. The fact that you were powerful enough to use the Symbol means great things for you, but there's time to speak of that later." } })
apply(1784, { "classic", "forever" }, { deDE = { progress = "Ihr seid zurück! Wie mich das freut, {name}. Meine Wunden sind verheilt und ich bin bereit, schnellstens zum Helmsbedsee zurückzukehren, sobald ich meine Frau davon überzeugt habe, dass es mir gut geht.", completion = "Ha-ha! Ihr habt es geschafft! Ihr habt Narm gerettet und den Beweis gefunden, den meine Frau braucht, um den Rat zu überzeugen. Einen solchen Segen des Lichts wie Euch sah ich noch nie... natürlich mit Ausnahme meiner Frau.\n\nNochmals danke, {name}." }, enUS = { progress = "Yer back! I'm glad to see it, {name}. My wounds are healed and I'm about ready to return to Helm's Bed lake as soon as I c'n convince me wife that I'll be fine.", completion = "Haha! You've done it! Ya saved Narm, and ya found the proof me wife needs to take to the council. Yer a blessin' o' the Light if I ever saw one... not includin' me wife o' course.\n\nThank ya again, {name}." } })
apply(1785, { "classic", "forever" }, { deDE = { completion = "Heute habt Ihr ganz Ironforge einen großen Gefallen getan, {name}. Ich bin stolz, dass Ihr zu uns gehört, und wenn Ihr bereit seid, würde ich Euch gern mit dieser Rolle segnen. Das Symbol des Lebens funktioniert nur bei einem {class}, der bereit ist, den größten Segen des Lichts zu empfangen - die Macht, die Toten ins Leben zurückzurufen.\n\nIch lehre Euch die Fähigkeit, Eure Gefährten wiederzubeleben. Nutzt sie weise, {name}, und habt Dank von mir, meinem Mann und ganz Ironforge." }, enUS = { completion = "You've done all of Ironforge a great favor today, {name}. I'm proud to count you among us, and if you feel you're ready, I would like to bless you with this scroll. The Symbol of Life would only have worked when used by a {class} who was ready for one of the Light's greatest blessings--the power to restore the dead back to life.\n\nI will teach you the ability to resurrect your companions. Use it wisely, {name}, and thank you, on behalf of myself, my husband, and Ironforge." } })
apply(1786, { "classic", "forever" }, { deDE = { completion = "Danke, Bruder.\n\nDa Ihr das Symbol des Lebens tragt, darf ich wohl annehmen, dass Euch Duthorian oder Gazin geschickt hat.\n\nIch wurde Opfer der Zauberer der Defias, als Gazin und ich ihnen ihre Pläne abnehmen wollten. Ich hielt lange genug durch, dass Gazin entkommen konnte, aber am Ende überwältigte mich ihre Magie.\n\nDoch Ihr konntet mich zurückholen: Nicht jeder besitzt die Fähigkeit, das Symbol zu benutzen, {name}. Es spricht für Euch, dass Ihr fähig wart, es durch Euren eigenen Glauben mächtig werden zu lassen." }, enUS = { completion = "Thank you, brother.\n\nSeeing you wield the Symbol of Life, may I assume Duthorian or Gazin sent you?\n\nI fell to the Defias spell casters while Gazin and I tried to get their plans from them: I was able to hold on long enough to allow Gazin to escape, but in the end, their magics overwhelmed me.\n\nBut you were able to bring me back: the ability to use the Symbol doesn't come to just anyone, {name}. It bodes well for you that you were able to empower it with your own faith." } })
apply(1787, { "classic", "forever" }, { deDE = { progress = "Ist Henze in Sicherheit, {name}? Hattet Ihr Erfolg?\n\nDurch Eure Fertigkeiten im Umgang mit Waffen und der Macht des Lichts sollte Heldenwache vor den Defias sicher sein, doch das müssen der König und seine Berater entscheiden.", completion = "Großartig! Ihr habt es geschafft und Henze gerettet. Das Licht ist eindeutig mit Euch, {name}!" }, enUS = { progress = "Is Henze safe, {name}? Were you successful?\n\nBetween your skill with a weapon, and the power of the Light, I'd imagine Heroes' Vigil is safe from any Defias threat, but that's for the King and his advisors to say.", completion = "Wonderful! You made it, and saved Henze. The Light is with you for sure, {name}!" } })
apply(1788, { "classic", "forever" }, { deDE = { completion = "Ihr habt Eure Sache heute gut gemacht, {name}. Ihr solltet stolz auf Eure Leistungen sein.\n\nUnd noch stolzer solltet Ihr auf Eure Fähigkeiten sein. Nicht jeder kann die Macht des Symbols des Lebens nutzen. Da Ihr das Licht rufen könnt, um die Toten zu erwecken, seid Ihr bereit für eine der größten Ehren eines Paladins: die Macht der Auferstehung.\n\nIhr werdet die Macht haben, gefallene Gefährten zurückbringen zu können, wie das bei Henze geschah.\n\nGehabt Euch wohl, {name}. Das Licht scheint auf Euch und Ihr solltet dankbar sein." }, enUS = { completion = "You've done well this day, {name}. You should take some pride in what you've accomplished.\n\nEven more so, you should be proud of your abilities. Not everyone can use the power of the Symbol of Life. Calling upon the Light to bring back the dead means you're prepared for one of the {class}'s greatest honors: the power of resurrection.\n\nYou shall have the power to bring back fallen companions much like you did for Henze.\n\nBe well, {name}. The Light shines upon you and you should welcome it wholly." } })
apply(1791, { "classic", "forever" }, { deDE = { completion = "Ihr seid weit gereist, junger {class}. Ich sehe Feuer in Euren Augen. Ihr sucht eine Waffe mit großer Macht, ja?\n\nIch kann Euch bei Eurer Suche helfen. Und Ihr mir bei meiner." }, enUS = { completion = "You have traveled far, young {class}.  I see fire in your eyes.  You seek a weapon of great power, yes?\n\nI can help you with your quest.  And you can help me with mine." } })
apply(1796, { "classic", "forever" }, { deDE = { progress = "Wie läuft Eure Suche nach den Roben, {name}? Habt Ihr selbst welche hergestellt? Diese persönlichen Feinarbeiten machen das Erfüllen mit Magie so viel schöner. Sie geben Euch eine große Befriedigung. Aber ich habe Verständnis, wenn Ihr Euch für den schnelleren Weg entschieden habt und sie habt herstellen lassen. Es hat schon was für sich ... ein solcher Ehrgeiz.", completion = "Das dürfte reichen, {name}.\n\nAlle magischen Gegenstände müssen mit einem Gegenstand von hoher Qualität beginnen. Je mehr Mühe und Können man in einen Gegenstand legt, desto größere Magie kann er aufnehmen. Seltene und teurere Komponenten halten die Magie besser. Ihr werdet nicht bereuen, diese Roben in jene mit einzubringen, die wir später für Euch machen werden." }, enUS = { progress = "How goes your search for the robes, {name}? Have you created them yourself? Such personal touches I find make the imbuing of magic that much sweeter. It gives you a greater sense of accomplishment. But I understand if you choose the quicker path and have it made for you--there's something to be said for such... ambition.", completion = "This will do nicely, {name}.\n\nAll magical items must begin with an item of high quality. The more effort and skill put into an item, the greater the magics it can hold. Rare and more expensive components hold the magic better. You will not regret having the robes fashioned into the ones we will make for you later on." } })
apply(1798, { "classic", "forever" }, { deDE = { completion = "{name}? Ah, natürlich. Unser neuestes Wunderkind. Leider entspricht die Realität nicht ganz der Legende.\n\nWie auch immer, Ihr seid gekommen um zu lernen, und nicht um anzuhören, wie ich Witze über Euch mache." }, enUS = { completion = "{name}? Ah, of course. Our latest prodigy. The real thing can't live up to the legend, I'm afraid.\n\nNo matter, you've come here to learn, not to hear me make jokes to myself." } })
apply(1802, { "classic", "forever" }, { deDE = { progress = "Haben sich die Gerüchte als zutreffend erwiesen, {name}?", completion = "Phantastisch! Nun gehöre ich zu den Wenigen, die seinen Inhalt gesehen haben.\n\nIch kann es kaum erwarten, den Text weiter zu studieren. Das ist ein großer Tag, {name}! Wenn Ihr mich nur einen Blick hineinwerfen lassen würdet, bevor Ihr geht. Ich bin sicher, Strahad wird bereit sein, mir eine Kopie zu schicken." }, enUS = { progress = "Did the rumors prove true, {name}?", completion = "Fantastic! Now I may join the ranks of the few that have spied its contents.\n\nI can't wait to further peruse this text. This is a great day, {name}! If you will just allow me to glance at it before you leave. I'm sure that Strahad will be willing to send me a copy." } })
apply(1803, { "classic", "forever" }, { deDE = { progress = "Mag sein, dass Ihr Hirngespinsten nachjagt, {name}, aber selbst die wildesten Gerüchte enthalten meist ein Körnchen Wahrheit.", completion = "Ach nein! Was haben wir denn hier?\n\nDas ist beeindruckend, {name}. Ich hätte es nie für möglich gehalten, aber hier halte ich den vollständigen Folianten der Kabale in Händen.\n\nLasst mich nur kurz die Seiten durchblättern bevor Ihr wieder geht." }, enUS = { progress = "It may be that you are chasing after fairy tales, {name}, but truth can be found at the center of even the wildest rumors.", completion = "Well well well! What do we have here?\n\nThis is impressive, {name}. I wouldn't have thought it possible, but here it is in my very hands, the complete Tome of the Cabal.\n\nAllow me to leaf through its pages for just a moment before you are off again." } })
apply(1805, { "classic", "forever" }, { deDE = { progress = "Ja, {name}? Wie kann ich Euch behilflich sein?", completion = "Gut gemacht! Der Foliant der Kabale und drei makellose - vermutlich nur leicht zerkratzte - Kanalisierungsruten.\n\nDas wird interessant. Es ist eine Weile her, seit ein junger {class} sich einen Teufelsjäger zugelegt hat." }, enUS = { progress = "Yes, {name}? Of what service can I be to you?", completion = "Well done! The Tome of the Cabal and three pristine--slightly scratched, I suppose--rods of channeling.\n\nThis will be interesting. It's been some time since a young {class} took on a felhunter to make his own." } })
apply(1806, { "classic", "forever" }, { deDE = { completion = "Da ist sie, {name}. Eine Waffe, wie sie einem Helden des Lichts würdig ist. Ich benannte sie nach einem großen Zwergenpaladin, der ein Freund von mir war. Sein Name war Verigan... Bosch Verigan. Bitte nehmt sie in meinem Namen und dem meiner Frau. Wir stehen tief in Eurer Schuld. Die Welt ist sicherer, wenn einer mit Euren Fähigkeiten durch das Land zieht." }, enUS = { completion = "Here it is, {name}. A weapon worthy of a champion of the Light such as yourself. I've named it after a great dwarven {class} who was a friend of mine. His name was Verigan... Bosch Verigan. Please take it on behalf of myself and my wife. We owe you a great debt, and the world will be a safer place with one of your skill traveling the land." } })
apply(1818, { "classic", "forever" }, { deDE = { completion = "Seid Ihr wegen einer Mission hier? Gut. Ich habe eine wichtige, die Eure Fertigkeiten im Gefecht auf die Probe stellt... und Eure Entschlossenheit, die Verlassenen zu verteidigen." }, enUS = { completion = "You're here for a mission?  Good.  I have an important one, and one that will test your skill in combat... and your resolve in the defense of the Forsaken." } })
apply(1819, { "classic", "forever" }, { deDE = { completion = "Gut gemacht, {name}. Ulag war kein unmaßgeblicher Agent der Geißel. Ihr habt den Todeswachen, und damit der dunklen Fürstin, gezeigt, dass Ihr ein geschickter und entschlossener {class} seid, und Euch damit weitere Ausbildung verdient." }, enUS = { completion = "Well done, {name}.  Ulag was no minor agent of the Scourge.  You have shown the Deathguards, and hence the Dark Lady, that you are a {class} of skill and resolve, and are worthy of further instruction." } })
apply(1820, { "classic", "forever" }, { deDE = { completion = "Ja, es stimmt. Ich brauche Eure Fertigkeiten im Gefecht. Meine Mittel sind bescheiden, doch meine Aufgabe hilft mir und der Sache der Verlassenen. Macht es, und Ihr werdet zweifache Belohnung erhalten." }, enUS = { completion = "Yes, it is true.  I have need for your skills in combat.  My means are small, but my task aids both me and the Forsaken's cause.  Do it, and your reward will be twofold." } })
apply(1821, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Erbstücke, {name}?", completion = "Ah! Ihr habt sie genommen! Jetzt ist das letzte Restchen Ehre und Andenken vom verfluchten Land der Agamands entfernt. Die Familie existiert wahrlich nicht mehr!" }, enUS = { progress = "Do you have the heirlooms, {name}?", completion = "Ah!  You retrieved them!  Now the last semblance of honor and memory is stripped from the cursed Agamand lands.  The family truly is no more!" } })
apply(1823, { "classic", "forever" }, { deDE = { completion = "Seid Ihr wegen meiner Prüfung hier, {name}?" }, enUS = { completion = "You are here for my trial, {name}?" } })
apply(1824, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Fühler? Wenn ja, gebt sie mir schnell, denn zuckende Fühler zucken nicht ewig...", completion = "Ordentlich gemacht, {name}! Mit der bestandenen Prüfung auf dem Feld der Riesen habt Ihr einen weiteren Schritt auf dem Weg des Kriegers getan." }, enUS = { progress = "Do you have the antennae?  If so then give them to me quickly, for twitching antennae do not twitch forever...", completion = "Nicely done, {name}!  In passing the trial at the Field of Giants, you take one more step down the {class}'s path." } })
apply(1825, { "classic", "forever" }, { deDE = { completion = "Ja, Ihr seid gekommen. Das ist gut, denn wir haben viel zu besprechen, wir beide." }, enUS = { completion = "Yes, you have come.  This is good, for we have much to discuss, you and I." } })
apply(1838, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Gegenstände auf meiner Rolle, {name}?", completion = "Ihr habt alles gebracht, worum ich Euch bat. Jetzt beginnt meine Arbeit..." }, enUS = { progress = "Do you have the items on my scroll, {name}?", completion = "You brought all that I asked.  Now, I will do my part..." } })
apply(1839, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {name}. Der alte Thun'grim ließ mich wissen, dass Ihr kommt, doch hätte er geschwiegen, hätte mich Eure Anwesenheit hier nicht überrascht.\n\nDie Geister wachen über Eure Fortschritte, junger {class}, und sagen mir, dass Ihr viele Feinde beseitigt habt." }, enUS = { completion = "Greetings, {name}.  Old Thun'grim sent word to me of your coming, but had he kept silent your presence here would not have surprised me.\n\nThe spirits follow your progress, young {class}, and they tell me that many foes have fallen before you." } })
apply(1840, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {class}. Ich bin Orm. Thun'grim sagte mir, Ihr wünscht einen Helm?" }, enUS = { completion = "Greetings, {class}.  I am Orm, and Thun'grim tells me you wish a helm made?" } })
apply(1841, { "classic", "forever" }, { deDE = { completion = "Seid Ihr wegen der Beinrüstung hier? Großartig!\n\nHm... mache ich die Rüstung für Euch oder Ihr sie für mich?\n\nDas war ein Witz. War er komisch? Ich weiß es nicht... Ich habe meinen Sinn für Humor im selben Moment wie meinen Geruchssinn verloren. Das war auch der Moment, als ich aufhörte zu atmen." }, enUS = { completion = "You are here for leg armor?  Great!\n\nUm... am I making the armor for you, or are you making it for me?\n\nThat was a joke.  Was it funny?  I can't tell... I lost my sense of humor the same time I lost my sense of smell.  Which was about the same time I stopped breathing." } })
apply(1842, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Hufe, {name}? Die Magie in ihnen ist stark.", completion = "Ah, Ihr habt sie! Jetzt werde ich die Macht in diesen Hufen absaugen und in meine Rüstung einfließen lassen, so wie die Satyrn die Stärke von Ashenvale absaugten." }, enUS = { progress = "Do you have the hooves, {name}?  The magic within them is strong.", completion = "Ah, you have them!  Now, just as the Satyrs leeched the strength of Ashenvale, I will leech the power held within these hooves and harness it into my crafting..." } })
apply(1844, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Horn? Ist die Matriarchin von Schmerzen befreit?", completion = "Ihr habt Eure Aufgabe beendet, {name}, und Euch als würdig und entschlossen erwiesen. Der Helm wird Euch gehören..." }, enUS = { progress = "Do you have the horn?  Is the matriarch free of pain?", completion = "You have completed your task, {name}, and shown me your worth and resolve.  The helm will be yours..." } })
apply(1846, { "classic", "forever" }, { deDE = { progress = "Ich warte auf diese Schienbeinknochen, {name}. Sie werden ein prächtiges Gestell für Eure Beinschützer.", completion = "Gut gemacht! Die sehen robust genug aus. Ich glaube, sie sind genau richtig. Wie haben die Orcs reagiert, als Ihr ihnen an die Schienbeinknochen wolltet, {name}? Haben Sie viel Getue gemacht?\n\nDas war wieder ein Witz. Ihr lacht ja gar nicht.\n\nIch bin heutzutage nicht mehr sehr komisch, oder?" }, enUS = { progress = "I'm waiting for those shinbones, {name}.  They'll make a nice frame for your leg guards.", completion = "Well done!  These all look strong.  I think they'll do quite nicely.  How did those orcs mind you taking their shins, {name}?  Complain much?\n\nThat was another joke.  You're not laughing.\n\nI'm not very funny these days, am I..." } })
apply(1858, { "classic", "forever" }, { deDE = { progress = "Ist es nicht verflixt, das Objekt der Begierde in Reichweite zu haben und trotzdem nicht ranzukommen?.", completion = "Hmm, also das ist interessant. Ihr habt Euren Wert damit mehr als bewiesen, {name}. Ich bin recht beeindruckt. Betrachtet Euch als neuestes Mitglied der Shattered-Hand. Und nehmt dies; ich glaube, es wird Euch in Zukunft eine große Hilfe sein." }, enUS = { progress = "Is it not vexing to have the subject of your desire within your grasp, but to have no way of getting to it?", completion = "Hmmm, now this is interesting. You've more than proved your worth with this, {name}. I am quite impressed. Consider yourself the newest member of the Shattered Hand. And take this, it will be a great help to you in the future, I think." } })
apply(1859, { "classic", "forever" }, { deDE = { completion = "Ausgezeichnet, ich bin froh, dass Kaplak Euer habhaft wurde.\n\nWir haben einiges zu besprechen, darunter auch Eure Zukunft bei der Hand." }, enUS = { completion = "Very good, I'm glad Kaplak was able to get a hold of you.\n\nWe have some things to speak of, not the least of which is your future with the Hand." } })
apply(1860, { "classic", "forever" }, { deDE = { completion = "Wurdet Ihr geschickt, um mich bei meiner Aufgabe zu unterstützen, {name}? Gut. Schön zu sehen, dass junge {class} darauf brennen, unsere Sache zu unterstützen...\n\nWas für eine Sache, fragt Ihr? Alles zu seiner Zeit. Zu gegebener Zeit werdet Ihr es erfahren." }, enUS = { completion = "You have been sent to aid me in my task, {name}?  Good.  It is heartening to see young mages eager to help in our cause...\n\nWhat cause, you ask?  In time, young one.  You shall know... in time." } })
apply(1861, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Probe, {name}? Der Fluss der Magie in Stormwind und Elwynn wurde verändert; ich muss wissen, ob sie in das Wasser sickert.", completion = "Danke, {name}. Ich werde das Wasser auf magische Eigenschaften hin prüfen. Hoffen wir, dass es keine enthält, sonst werden alle, die zu lange aus dem Spiegelsee trinken, negativ beeinflusst.\n\nHier, {name}. Nehmt diese Kugel oder diesen Stab als Zeichen dafür, dass Ihr mir gute Dienste geleistet habt. Was Ihr auch wählt, es möge Euch nützlich sein." }, enUS = { progress = "Do you have the sample, {name}?  The flow of magic in Stormwind and Elwynn has been altered, and I must know if it is seeping into the water.", completion = "Thank you, {name}.  I will test this water for magical properties.  Let us hope that it contains none, or we may find that those who drink from Mirror Lake for too long will be adversely affected.\n\nHere, {name}.  Take this orb or staff as a token of your service.  May it serve you well." } })
apply(1880, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meinen Gizmonitor gefunden? Ich muss ihn haben, ehe sein Energievorrat aufgebraucht ist!", completion = "Na großartig! Als ich meinen Gizmonitor herstellte, hatte ich keine Ahnung, wie abhängig ich einmal davon werden würde. Jetzt kann ich mit meinen Studien von vorn beginnen!\n\nDanke, {name}! Und hier - das waren meine allerersten Magierwerkzeuge. Sie sind ein wenig zerkratzt, haben sich aber immer bewährt. Sucht Euch eines davon aus - ich bin sicher, Ihr werdet es nützlich finden." }, enUS = { progress = "Did you find the gizmonitor?  I must have it before its energy supply runs out!", completion = "Oh, splendid day!  When I made the gizmonitor I never realized how dependent on it I would become.  Now I can begin my studies anew!\n\nThank you, {name}!  And here--these were my first tools as a {class}.  They're a little scratched but they're well tested.  Take your pick--I'm sure you'll find either of them useful." } })
apply(1881, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {name}. Ihr wart weise, meinem Ruf zu folgen. Noch weiser wäre es, meine folgenden Worte zu beachten..." }, enUS = { completion = "Greetings, {name}.  You were wise to answer my call, and wiser still if you heed what I next say..." } })
apply(1882, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Löwenmäulchen? Diese Pflanzenart ist höchst empfänglich für magische Energien. Das Studium der Löwenmäulchen aus der unmittelbaren Nähe der Pestländer kann uns sagen, ob die Seuche schon in Tirisfal eingedrungen ist.", completion = "Ah, das ist ein wunderbares Exemplar. Ich schicke es zu unseren Apothekern, damit sie das Ausmaß der Besudelung der Pestländer bestimmen können.\n\nGut gemacht, {name}. Als Dank für Eure Dienste, habt Ihr die Wahl: Wollt Ihr eine Kugel oder einen Stab? Was auch immer wählt, Ihr werdet es recht nützlich finden." }, enUS = { progress = "Do you have the snapdragons?  That breed of flower is highly receptive to magic energies, and studying the snapdragons so close to the Plaguelands can tell us if the plague has entered Tirisfal Glades.", completion = "Ah, a fine specimen this is.  I will send it to be studied by our apothecaries to determine the extent of the Plagueland's taint.\n\nWell done, {name}.  For your services, I present to you this choice: an orb or staff.  Whichever you choose, you will find it quite useful." } })
apply(1883, { "classic", "forever" }, { deDE = { completion = "Grüße, {name}. Gelobet seid Ihr, denn meine Bitte um Unterstützung wurde erhört. Hoffen wir, dass Ihr der Aufgabe gewachsen seid..." }, enUS = { completion = "Hail, {name}.  Praise to you, for my call for aid is now answered.  Let us hope you are up to the task..." } })
apply(1884, { "classic", "forever" }, { deDE = { progress = "Ihr müsst Euch beeilen, {name}. Zerstört die Jujuhaufen!", completion = "Ich spüre, dass Zalazanes Jujuhaufen zerstört wurden. Mit Zeit und etwas Glück wird sich der Fluss der Magie in Durotar wieder normalisieren.\n\nIhr habt eine Großtat für Euer Volk vollbracht, {name}. Und Ihr habt Euch unser, der {class} der Horde, als würdig erwiesen." }, enUS = { progress = "You must hurry, {name}.  Destroy the ju-ju heaps!", completion = "I sense that Zalazane's ju-ju heaps were destroyed, and with time, and luck, the flow of magic in Durotar will return to normal.\n\nA great deed you have done for your people, {name}.  And you have shown your worth to us, the mages of the Horde." } })
apply(1885, { "classic", "forever" }, { deDE = { completion = "Hm. Ihr seid zweifellos in dem Augenblick hierher gekommen, als Ihr meinen Ruf vernommen habt, nicht? Natürlich. Von einem angehenden Todespirscher hätte ich nichts anderes erwartet." }, enUS = { completion = "Hm. No doubt you made your way here at first mention of my summons, yes? Of course. I would expect no less from a prospective Deathstalker." } })
apply(1886, { "classic", "forever" }, { deDE = { progress = "Erfolgsmeldung?", completion = "Gut gemacht, {name}. Ihr habt den ersten Teil dieser Prüfung bestanden. Hoffentlich hat Andron keinen Wind von Euren Aktivitäten bekommen, sodass wir ihn davon überzeugen können, dass Ihr wirklich der Bote seid, den er erwartet." }, enUS = { progress = "Success to report?", completion = "Well done, {name}. You've passed the first part of this test. Hopefully Andron will not have caught wind of your activities, and we will be able to convince him that you are, in fact, the messenger he is expecting." } })
apply(1898, { "classic", "forever" }, { deDE = { progress = "Hallo. Kann ich etwas für Euch tun?", completion = "Ah, ja, ich habe Euch erwartet. Ich darf davon ausgehen, dass unsere gemeinsamen Bekannten mit den Informationen, die ich bisher lieferte, zufrieden waren?\n\nVermutlich hat es keinen Sinn, Euch zu fragen. Ich bezweifle, dass sie Euch mit diesem Wissen belasten würden. Warum so viel Vertrauen in den Boten setzen, hm?" }, enUS = { progress = "Hello. Something I can do for you?", completion = "Ah, yes, I've been expecting you. I have no doubt our mutual acquaintances are pleased with the information that I have provided so far?\n\nI suppose there's no point in asking you, I doubt they would burden you with this knowledge. Why place so much trust in the messenger, hm?" } })
apply(1899, { "classic", "forever" }, { deDE = { progress = "Erfolg, {name}?", completion = "Das sind eindeutig mehr Informationen, als ich mir je von Andron erhofft hätte. Lasst sie mich einen Moment studieren, bevor ich Euch Eure nächste Aufgabe nenne." }, enUS = { progress = "Success, {name}?", completion = "Well, this is certainly more information than I suspected to get out of Andron. Give me a moment to peruse it, before I set you to your next task." } })
apply(1918, { "classic", "forever" }, { deDE = { progress = "Ja, was wollt Ihr?", completion = "Ihr findet eine eklige Kugel aus Wasser und beschließt, sie mir zu bringen? Wer bin ich denn, der Irdene Ring oder was?\n\nMoment mal, das bringt mich auf eine Idee... vielleicht braucht Ihr den Irdenen Ring dafür. Ich meine, wenn es dabei hilft, die Situation am See endgültig zu klären, dann bin ich absolut dafür.\n\nIhr wisst, wer der Irdene Ring ist, {name}?" }, enUS = { progress = "Yeah, what do you need?", completion = "You find a nasty ball of water and decide to bring it to me?  Who am I, the Earthen Ring or something?\n\nActually, that does give me an idea... perhaps you do need the Earthen Ring for this.  I mean, if it helps clear up the situation at the lake for good, then I'm all for it.\n\nYou know who the Earthen Ring are, {name}?" } })
apply(1919, { "classic", "forever" }, { deDE = { completion = "{name}, ich habe eine Mission für Euch hier im Magierviertel. Hört genau zu, denn es gilt, keine Zeit zu verschwenden." }, enUS = { completion = "{name}, I have a mission for you, here in the {class} district.  Listen closely, for there is no time to waste." } })
apply(1920, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Kreaturen gefangen, {name}? Sie müssen untersucht werden, damit wir den Grund für ihr Kommen herausfinden.", completion = "Sehr gut gemacht! Ich werde diese Kreaturen studieren und mit Geschick und Glück herausfinden, wie sie in unsere Welt gelangen konnten.\n\nEuer Wert für die Gesellschaft der {class} wächst, {name}." }, enUS = { progress = "Have you captured the creatures, {name}?  They must be studied in order to determine the reason behind their arrival.", completion = "Very well done!  I will study these creatures and, with diligence and luck, determine how they slipped into our world.\n\nYour value to the society of mages grows, {name}." } })
apply(1921, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Jennea sagte mir, dass Ihr kommt. Habt Ihr etwas für mich?", completion = "Ja, das sind großartige Leinentücher. Daraus kann ich eine prima Robe machen. Und sobald die Rissedelsteine hineingewoben sind, haben wir ein Gewand, das eines Magiers würdig ist!" }, enUS = { progress = "Hello, {name}.  Jennea told me you would come.  Do you have something for me?", completion = "Yes, these are great pieces of linen.  I can make a fine robe with them.  And after I weave the rift gems into it, we'll have a garment fit for a {class}!" } })
apply(1938, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Buch, {name}? Seine Geheimnisse sind nicht für die Ungeübten bestimmt, das Studium seines Inhalts kann zu Verdammnis und Ruin führen.", completion = "Ich hatte befürchtet, dass Morganth das Buch anderswo versteckt oder einen Weg gefunden haben könnte, es zu öffnen und den Inhalt zu lesen.\n\nEin Glück, dass ihm das nicht gelang und die Siegel, mit denen wir 'Urs Abhandlung über Schattenmagie' sicherten, unversehrt sind." }, enUS = { progress = "Do you have the book, {name}?  Its secrets are not meant for the untrained, and plumbing its depths can lead to doom and ruin.", completion = "I feared that Morganth had hidden the book elsewhere, or that he had found a way to open it and read its contents.\n\nIt is good to see that he did not, and that the seals we placed on Ur's Treatise on Shadow Magic still hold." } })
apply(1939, { "classic", "forever" }, { deDE = { completion = "Seid gegrüßt, {name}. Ich freue mich, Euch zu sehen, und hoffe, Ihr habt Zeit, den Worten eines alten Mannes zu lauschen..." }, enUS = { completion = "Greetings, {name}.  I am pleased to see you, and hope you have time to listen to an old man's words..." } })
apply(1940, { "classic", "forever" }, { deDE = { progress = "Ah, ja. Die {class} im Magiersanktum sagten, dass Ihr mit mir sprechen wollt. Habt Ihr die benötigte Seide?", completion = "Das sind herrliche Exemplare. Ich mach mich gleich an die Arbeit!" }, enUS = { progress = "Ah, yes.  The mages of the Wizard's Sanctum said you'd speak with me.  Do you have the required silk?", completion = "Nice specimens, these.  I'll get right to work!" } })
apply(1943, { "classic", "forever" }, { deDE = { completion = "Gut, Ihr seid gekommen. Meine Aufgabe ist nicht leicht, aber für die Gesellschaft der {class} von entscheidender Bedeutung. Wenn Ihr mich unterstützt, soll es Euer Schaden nicht sein." }, enUS = { completion = "Good, you have come.  My task is not an easy one, but vital to the society of mages.  If you aid me, I am sure you will find it worthwhile." } })
apply(1944, { "classic", "forever" }, { deDE = { progress = "Ich sehe mit Freuden, dass Ihr mit heiler Haut zurückgekehrt seid, {name}. Habt Ihr die Wasserprobe? Ich kann es kaum erwarten, ihre Eigenschaften zu studieren.", completion = "Ah, sehr gut. Die Satyrn von Xavian haben Euch doch hoffentlich nicht allzu viele Schwierigkeiten gemacht?\n\nDanke, {name}. Ich werde diese Wasserprobe aus Xavian unverzüglich untersuchen." }, enUS = { progress = "I am pleased you have returned with your skin intact, {name}.  Do you have the water sample?  I am eager to study its properties.", completion = "Ah, very good.  I trust the satyrs of Xavian gave you little trouble?\n\nThank you, {name}.  I will study this sample of Xavian water immediately." } })
apply(1945, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {name}. Deino sagte, Ihr würdet kommen und die Haare der lachenden Schwestern bringen. Habt Ihr sie?", completion = "Ah, aus diesem Haar lässt sich eine edle Robe wirken, {name}. Leider mussten die lachenden Schwestern dafür sterben, aber ich fürchte, freiwillig hätten sie sich nie davon getrennt.\n\nEin Verlust, aber kein sehr großer." }, enUS = { progress = "Greetings, {name}.  Deino said you would come, and would bring the laughing sisters' hair.  Do you have it?", completion = "Ah, this hair will weave into a fine robe, {name}.  It is a pity the laughing sisters had to die to part with it, though I do doubt they would ever give it willingly.\n\nA pity, but only a small one." } })
apply(1947, { "classic", "forever" }, { deDE = { completion = "Still! Ich bin an einer komplizierten Prozedur und darf nicht gestört werden!\n\nEinen Moment..." }, enUS = { completion = "Quiet!  I'm in a delicate juncture and mustn't be disturbed!\n\nOne moment..." } })
apply(1948, { "classic", "forever" }, { deDE = { progress = "Hallo, {name}. Habt Ihr die Gegenstände, die ich benötige?", completion = "Aha! Ihr habt die Jade und den Dornbusch! Gut gemacht!\n\nSehe ich da Rauch aus Euren Ohren aufsteigen? Vielleicht seid Ihr zu nahe rangekommen, als der Blitzschlag in die Totemstecken eingeschlagen hat, aber keine Bange. Vom Blitzschlag getroffen zu werden bringt Glück!" }, enUS = { progress = "Hello, {name}.  Do you have the items I require?", completion = "Aha!  You got the jade and made the bramble!  Well done!\n\nIs that smoke I see rising from your ears?  You might have gotten too close when the lightning struck the totem sticks, but don't worry.  Being hit by lightning is good luck!" } })
apply(1949, { "classic", "forever" }, { deDE = { completion = "Was? Sprecht lauter! Diese alten Ohren sind nicht mehr das, was sie mal waren.\n\nIch hoffe, Ihr habt einen Becher frisches Bier oder einen heißen Tipp für das nächste Rennen! Wenn nicht, trollt Ihr Euch besser... denn ich habe einen Zauberstab der Verwandlung, den ich sonst geneigt wäre, an Euch auszuprobieren!" }, enUS = { completion = "What?  Speak up!  These old ears aren't as sharp as they used to be.\n\nWell, I hope you're here with a fresh mug of ale or some hot tips on the next race!  If not, then you best keep walking... because I have a polymorph wand with your name on it!" } })
apply(1950, { "classic", "forever" }, { deDE = { progress = "Worauf wartet Ihr? Ich brauche meinen magischen Satz!", completion = "Ah, jetzt erinnere ich mich...\n\nIch hatte den kleinen Fluch vergessen, mit dem ich Johnson belegt hatte. Ich kann mich nicht erinnern, warum ich das gemacht habe, aber gewiss geschah es ihm recht, dem kleinen Tunichtgut!" }, enUS = { progress = "What are you waiting for?  I need my magic phrase!", completion = "Ah, now I remember...\n\nI had forgotten about that little curse I put on Johnson.  I can't remember why I did it but I'm sure it served him right, the little ingrate!" } })
apply(1951, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt, {name}. Und habt Ihr das Buch 'Rituale der Macht' gefunden?", completion = "Das ist es! Genau das brauche ich, um das Ritual für die Herstellung Eures Zauberstabs vorzubereiten. Ich hoffe, es war nicht allzu schwer zu finden..." }, enUS = { progress = "Greetings, {name}.  Did you find the book, Rituals of Power?", completion = "That's it!  It's just what I need to prepare for the ritual to create your wand!  I hope it wasn't too much trouble to find..." } })
apply(1952, { "classic", "forever" }, { deDE = { completion = "Hier sind die Zauberstäbe, die ich hergestellt habe. Sucht Euch einen aus!" }, enUS = { completion = "Here are the wands I made.  Take your pick!" } })
apply(1953, { "classic", "forever" }, { deDE = { completion = "Ah, ja. Seid Ihr wegen einer Kugel oder eines Stabs hier, {name}? Wohlan denn. Ich helfe Euch bei der Konstruktion.\n\nDoch seid gewarnt - der Vorgang ist gefährlich und könnte tödlich für Euch enden.\n\nOder für mich. Für irgendwen könnte er jedenfalls tödlich enden ... \n\nHoffen wir, dass es jemand anderes ist, hm?" }, enUS = { completion = "Ah, yes.  You are here for an orb or a staff, {name}?  Very well.  I will aid you in its construction.\n\nBut be forewarned--the process is a perilous one and could mean your death.\n\nOr my death.  Definitely someone's death... \n\nBut let's hope it's someone else's death, eh?" } })
apply(1954, { "classic", "forever" }, { deDE = { progress = "Habt Ihr eine Höllenkugel, {name}?", completion = "Oh, ist die aber gut! Nein, ich meine nicht \"gut\", wie kühler Saft an einem heißen Tag gut ist.\n\nWenn ich darüber nachdenke, ist das sogar alles andere als gut. Nicht der Saft. Die Kugel!\n\nKonzentriert Euch, {name}! Ihr müsst konzentriert sein, wenn wir unsere Aufgabe je vollenden sollen!" }, enUS = { progress = "Do you have an infernal orb, {name}?", completion = "Oh, that's a nice one!  No, I don't mean it's \"nice\" like cool juice is nice on a hot day.\n\nIn fact, it's very NOT nice now that I think about it.  Not the juice.  The orb!\n\nFocus, {name}!  We'll need you focused if we're ever to finish our task!" } })
apply(1955, { "classic", "forever" }, { deDE = { completion = "Ordentlich gemacht, {name}! Diese Lektion wird der Dämon nicht so schnell vergessen.\n\nEr wird es sich zweimal überlegen, ehe er seinen hässlichen Kopf noch einmal in diese Welt steckt und nach dem dummen sterblichen Wesen sucht, das ihn besiegt hat. Diesmal wahrscheinlich mit Freunden. Großen, schuppigen Freunden, die nichts lieber machen als Euch in kleine {race}-Stücke zu reißen.\n\nIch hab Euch doch keine Angst gemacht, oder ...{name}?" }, enUS = { completion = "Nicely done, {name}!  You gave that demon a lesson he won't soon forget.\n\nHe'll think twice before he sticks his ugly head back in this world, looking for the stupid mortal who beat him.  Probably with friends this time.  Big, scaly friends who'd want nothing more than to tear you into little {race} pieces.\n\nI didn't scare you, did I...{name}?" } })
apply(1956, { "classic", "forever" }, { deDE = { progress = "Wart Ihr schon in Uldaman, {name}? Habt Ihr die Obsidianschildwache besiegt?", completion = "Wirklich? Gut gemacht!\n\nIch habe mich mit ein paar Kollegen unterhalten, wir kamen auf Euch zu sprechen und da haben die gesagt: \"Es ist ja allseits bekannt, dass {name} unter Druck gute Arbeit leistet!\"\n\nAber als ich ihnen erzählt habe, dass ich Euch nach Uldaman geschickt habe, um gegen die Obsidianschildwache anzutreten, da haben die gesagt, ich sei verrückt! Sie haben gesagt: \"Tabetha, du bist verrückt! Nie im Leben wird {name} mit dieser Schildwache fertig!\"\n\nDa habe ich gesagt: \"Abwarten\", und dann haben die gesagt: \"Ja, abwarten...\"\n\nDenen haben wir es aber gezeigt, was?" }, enUS = { progress = "Have you been to Uldaman, {name}?  Did you defeat the obsidian sentinel?", completion = "You did it?  Well done!\n\nI was chatting with some of my colleagues and when your name came up they said, \"You know that {name} sure works well under stress!\"\n\nBut when I told them I sent you to Uldaman against the obsidian sentinel, they said I was crazy!  They said, \"Tabetha, you're crazy!  There's no way {name} could take on that sentinel!\"\n\nAnd I said, \"We'll see,\" and then they said \"Yeah, we'll see...\"\n\nWell we sure showed them, didn't we!" } })
apply(1957, { "classic", "forever" }, { deDE = { completion = "Ihr habt es geschafft! Ich habe keinen Augenblick an Euch gezweifelt! Na gut, vielleicht einen klitzekleinen Augenblick... aber an sich hegte ich wenig Zweifel.\n\nEhrlich." }, enUS = { completion = "You did it!  I never doubted you for a second!  Ok, maybe for just a second, or two... but basically I didn't have much doubt.\n\nHonest." } })
apply(1959, { "classic", "forever" }, { deDE = { completion = "Es stimmt. In unserer Stadt wurde eine magische Störung entdeckt. Wir sind noch nicht sicher, woher sie kommt oder ob sie schädlich oder nützlich ist. Wir müssen mehr Informationen sammeln...\n\nUnd damit, {name}, sind wir bei Eurer Aufgabe." }, enUS = { completion = "It is true.  A magical disturbance has been detected in our city.  We are not yet sure of its origin, or whether it is malign or benign.  We must first gather more information...\n\nAnd that, {name}, brings us to your task." } })
apply(1960, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Störung untersucht, {name}? Habt Ihr die Kreaturen gefangen?", completion = "Sehr gut, {name}. Unsere größten Denker werden die Kreaturen in diesen Verwahrungskästen studieren und den Grund für ihre Anwesenheit in Undercity herausfinden.\n\nWenn ihre Anwesenheit auf einem Riss im natürlichen Fluss der Magie beruht, müssen wir herausfinden, ob es ein zufälliger Riss war. Wenn er nicht zufällig, sondern ein Angriff einer magischen Macht ist, müssen wir uns gegen zukünftige, gravierende Störungen wappnen." }, enUS = { progress = "Have you investigated the disturbance, {name}?  Have you captured the creatures?", completion = "Very good, {name}.  The creatures within these containment coffers will be studied by our finest minds, and the reason behind their presence in the Undercity will be determined.\n\nIf their appearance is caused by a rift in the natural flow of magic, then we must determine if the rift was random.  If it was not random, but instead an attack by some magical force, then we must prepare for future, more serious disturbances." } })
apply(1961, { "classic", "forever" }, { deDE = { progress = "Anastasia sagte, Ihr würdet zu mir kommen. Ich bin bereit, Eure Robe zu schneidern. Habt Ihr die Edelsteine und das Leinen?", completion = "Das ist ausgezeichnetes Material. Mir fehlt das Talent, die Qualität dieser Manaedelsteine abzuschätzen, aber wir werden bald wissen, ob sie die Macht besitzen, die für die Herstellung von Roben des Zauberfeuers erforderlich ist..." }, enUS = { progress = "Anastasia said you would come to me, and I am prepared to fashion your robes.  Do you have the gems and the linen?", completion = "This is very good material, and although I lack the talent to gauge the quality of these mana gems, we'll soon know if they possess the power needed to create spellfire robes..." } })
apply(1963, { "classic", "forever" }, { deDE = { progress = "Ein Narr, der glaubt, ein Sturmlauf mit erhobener Axt sei gefährlicher als ein Messer im Dunkeln.", completion = "Hm, zwar höre ich erfreut, dass Tazan nicht mehr unter uns weilt, aber ein verschlossener Ranzen nützt uns nichts. Wir brauchen die darin enthaltenen Informationen.\n\nDas sollte eine würdige zweite Herausforderung für einen sein, der sich der Shattered-Hand anschließen möchte." }, enUS = { progress = "It is a fool who believes a charge with axe drawn is more dangerous than a knife in the dark.", completion = "Hm, while I am glad to hear that Tazan is no longer with us, a locked satchel does us no good. We need the information kept within.\n\nThis should prove a worthy second challenge for one who wishes to join the Shattered Hand." } })
apply(1978, { "classic", "forever" }, { deDE = { progress = "Ja?", completion = "Hmm, das ist interessant. Die Todespirscher haben ihre Pflicht bei der Erledigung dieser Aufgabe meisterlich erfüllt.\n\nSoweit ich informiert bin, verdient Ihr ebenfalls Lob für Eure Leistung. Ich hoffe, dass das bei Euch zur Gewohnheit wird, {name}, meine Todespirscher haben immer Verwendung für gute Männer." }, enUS = { progress = "Yes?", completion = "Hmm, this is interesting. The Deathstalkers have performed their duties admirably in ferreting this out.\n\nFrom what I understand, you also deserve commendation for your performance. I hope that this will become routine for you, {name}, my Deathstalkers always have use of a good man." } })
apply(1998, { "classic", "forever" }, { deDE = { progress = "Ich habe größtes Vertrauen darin, dass Ihr diesen Dienst für Lord Varimathras erledigt.", completion = "Ihr habt Eure Sache gut gemacht, {name}. Mir fällt ein, dass Ihr den Todespirschern viele Dienste geleistet und damit Euren Wert bewiesen habt. Vielleicht ist es an der Zeit, dass wir Eure Ausbildung in den Schattenkünsten fortsetzen." }, enUS = { progress = "I have placed the utmost faith in you to perform this service for Lord Varimathras.", completion = "You've done well, {name}. It occurs to me that you have performed many services for the Deathstalkers, proving your worth, and that perhaps it is time that we furthered your training in the shadow arts." } })
apply(1999, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Dokumente gefunden, {name}?", completion = "Sehr gut, {name}! Ihr habt die hohe Kunst des Schlossknackens schnell gelernt... schneller als ich je für möglich gehalten hätte.\n\nMein Vertrauen in Euch war also nicht unbegründet. Glaubt mir, Jungchen, ich sehe eine große Zukunft in diesem Metier für Euch." }, enUS = { progress = "Have you located the documents, {name}?", completion = "Very good, {name}! You have learned the fine art of lockpicking well, and faster than I could have possibly expected.\n\nI see that I was right to place my trust in you. Believe me, boy, I foresee that you will go far in this line of work." } })
apply(2038, { "classic", "forever" }, { deDE = { progress = "{name}! Wo sind meine Sachen?!", completion = "Ihr habt der Bewegung einen großen Dienst erwiesen, {name}. Die Troggs und Lepragnome, die Gnomeregan verschandeln, werden bald die Wucht eines Gnomenluftangriffs spüren!" }, enUS = { progress = "{name}! Where are my things?!", completion = "You've done the movement a great service, {name}. The troggs and leper gnomes infesting Gnomeregan will soon feel the brunt of a gnomish air assault!" } })
apply(2039, { "classic", "forever" }, { deDE = { completion = "Gnoarn hat also kein Vertrauen in meine Aufklärungsfähigkeiten? Warum nur...\n\nUnwichtig, ich brauche Eure Unterstützung! Nee! Die Bewegung braucht Eure Unterstützung!" }, enUS = { completion = "So Gnoarn doesn't trust my reconnaissance abilities? I wonder why...\n\nNevermind that, I need your assistance! Nay! The movement needs your assistance!" } })
apply(2040, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Gnoam-Sprecklesprocket gefunden, {name}?", completion = "Gut gemacht, {name}. Dank Euch ist Gnomeregan dem Tag der Befreiung einen Schritt näher!" }, enUS = { progress = "Have you found the Gnoam Sprecklesprocket, {name}?", completion = "Well done, {name}. Thanks to you, Gnomeregan is one step closer to its day of liberation!" } })
apply(2041, { "classic", "forever" }, { deDE = { completion = "Bringt Ihr Kunde vom Zentralkommando?" }, enUS = { completion = "Do you bring word from central command?" } })
apply(2078, { "classic", "forever" }, { deDE = { progress = "Wo is mein Erster Maat, {name}? Mast und Schotbruch, beeilt Euch gefälligst!", completion = "Harrr... Ihr habt gezeigt, dass Ihr 'n richtiger alter Seebär seid, Landratte.\n\nWenn Ihr so weitermacht, befördert Euch der Käpt’n bald zum Deckschrubber..." }, enUS = { progress = "Where be me first mate, {name}? Shackles n' sharks fer ye soon if ye don't hurry!", completion = "Yarrr... Ye be provin' yerself to be more than a yella sea dog, landlubber.\n\nThe Cap'n may promote ye to poop deck swabby if ye be keepin' this up..." } })
apply(2098, { "classic", "forever" }, { deDE = { progress = "Habt Ihr meinen zerbrochenen Schlüssel gefunden, Landratte?", completion = "Potzblitz, Ihr elender Seebär! Ihr habt's geschafft! Bald ist mein Erster Maat wieder funktionstüchtig und wird die Biesterchen das Fürchten lehren!\n\nHrm, habt Ihr meinen Ersten Maat gesehen?" }, enUS = { progress = "Have ye found me broke down key, landlubber?", completion = "Avast ye scurvy sea dog! Ye did it! Soon me first mate be back in workin' order and them beasties won't know what hit em!\n\nHrm, have ye seen me first mate?" } })
apply(2118, { "classic", "forever" }, { deDE = { completion = "Eure Arbeit hat erst begonnen, {name}. Seid Ihr bereit für die nächste Aufgabe?" }, enUS = { completion = "Our work has only just begun, {name}. Are you prepared for your next task?" } })
apply(2138, { "classic", "forever" }, { deDE = { completion = "Ihr habt Auberdine einen großen Dienst erwiesen, {name}, doch Eure Arbeit ist noch nicht getan.\n\nKommt wieder zu mir, wenn Ihr Euch erholt habt.\n\n... und {name}, bereitet Geist und Seele auf weiteres Blutvergießen vor." }, enUS = { completion = "You have done Auberdine a great service, {name}, but your task is not yet complete.\n\nReturn to me once you have rested.\n\n...and {name}, prepare your mind and soul for more bloodshed." } })
apply(2139, { "classic", "forever" }, { deDE = { completion = "Ihr habt tapfer und ehrenhaft für Auberdine gekämpft, {name}. In unserem vom Krieg gebeutelten Land sind Tod und Verzweiflung an der Tagesordnung. Viele werden der Herausforderung, in unserer neuen Heimat zu leben, nicht gewachsen sein und sich stattdessen in ihren Häusern verbergen oder in die wehrhafteren Länder der Allianz abwandern.\n\nDanke, {name}. Vielleicht werden wir eines Tages als Kameraden gegen einen neuen Feind antreten." }, enUS = { completion = "You have fought for Auberdine with bravery and honor, {name}. In our war torn lands, death and despair are common. Many will not rise to meet the challenge of life in our new home, choosing instead to hide in their homes or escape to the more fortified lands of the Alliance.\n\nThank you, {name}. Perhaps someday soon we shall fight along side as comrades versus another foe." } })
apply(2158, { "classic", "forever" }, { deDE = { completion = "Ruhe und Entspannung für die Müden und Frierenden - das ist unser Leitspruch! Bitte setzt Euch ans Feuer und wärmt Eure müden Knochen.\n\nMöchtet Ihr von unseren erlesenen Speisen und Getränken kosten?" }, enUS = { completion = "Rest and relaxation for the tired and cold -- that's our motto! Please, take a seat by the fire and rest your weary bones.\n\nWould you like to try a sampling of some of our fine food and drink?" } })
apply(2159, { "classic", "forever" }, { deDE = { progress = "Wie vermag ich Euch dienlich zu sein, junger Freund? Seid Ihr hier, um Euch im Gasthaus auszuruhen? Benötigt Ihr einen Ruhestein?", completion = "Ah, ja, die Lieferung Kräuter aus Shadowglen. Ein Jammer, dass Porthannius nicht selbst kommen konnte, denn wir hätten viel zu besprechen. Dennoch bin ich froh, dass ich die Kräuter habe und dass Ihr gekommen seid.\n\nBitte ruht Euch aus solange Ihr hier seid. Helden müssen Körper und Geist fit halten und Ruhe und Entspannung suchen, wann immer sie können. Vernachlässigt man Ruhe für Körper und Geist, wird man keine Leistung bringen können.\n\nAlso ... ruht Euch aus." }, enUS = { progress = "How might I be of service to you, young one?  Are you here to rest in the inn?  Do you require a hearthstone?", completion = "Ah yes, the delivery of herbs from Shadowglen.  It is a shame Porthannius could not bring it himself, for we have much to discuss, he and I.  But I am glad to get the herbs nonetheless, and I am glad you came.\n\nWhile you are here, please, rest yourself.  Heroes must keep their strength and spirits high, and must find rest and solace whenever they may.  For to neglect one's peace of body and mind is a sure path to failure.\n\nSo... rest." } })
apply(2160, { "classic", "forever" }, { deDE = { progress = "Hallo, Ihr da! Kommt herein, setzt Euch ans Feuer und wärmt Euch mit einem Krug Bier.", completion = "Ah, endlich die Vorräte von Hands! Ich hatte mir schon Sorgen gemacht, seit die Troggs den Pass überrannt haben, hören wir kaum etwas aus Anvilmar.\n\nDanke, dass Ihr mir das gebracht habt, {name}. Und bitte macht es Euch bequem. Ihr müsst nach der langen Reise müde sein." }, enUS = { progress = "Hi there! Come in, take a seat by the fire and warm yourself with a flagon of ale.", completion = "Ah, at last, the supplies from Hands! I was beginning to worry, we've had scarce word from Anvilmar ever since the troggs overran the pass.\n\nThanks for bringing this to me, {name}. And please, make yourself comfortable. You must be tired after your journey." } })
apply(2178, { "classic", "forever" }, { deDE = { progress = "Der Topf ist leer und ich habe Hunger! Was hat Euch so lange aufgehalten?", completion = "Phantastisch! Kostet und sagt mir, was Ihr davon haltet, {name}!" }, enUS = { progress = "The pot is empty and I'm hungry! What's taking you so long?", completion = "Fantastic! Try it and tell me what you think, {name}!" } })
apply(2198, { "classic", "forever" }, { deDE = { progress = "Ihr habt den falschen Gnom erwischt, Kumpel! Da bin ich nie gewesen! Ihr könnt gar nichts beweisen!\n\nMoment mal... Wer seid Ihr? Was, zum... Wo habt Ihr diese Halskette gefunden?", completion = "Ja... Ich bin der Juwelier, der die Halskette hergestellt hat. Aber ich betreibe dieses Geschäft nicht, um Informationen ohne jede Gegenleistung herauszugeben. Informationen sind nämlich nie umsonst. Wenn ich Euch helfen soll, müsst Ihr zuerst MIR helfen." }, enUS = { progress = "You've got the wrong gnome, pal!  I was never there!  You can't prove anything!\n\nWait a second... who are you?  What the... where did you find this necklace at?", completion = "Yes... I am the jeweler who made this necklace.  I also am not in the business of handing out information as though it were free.  Information is never free, friend.  If I am going to help you out, you need to help ME out first." } })
apply(2199, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die fünf Silberbarren, um die ich bat? Ich erzähle Euch die traurige Geschichte dieser Halskette in Eurem Besitz... aber erst, wenn ich diese Barren habe! Helft doch einem armen Gnom, ja?", completion = "Also ICH mag Euch, es ist mir ganz egal, was andere sagen... Nur ein Witz, nur ein Witz! Ganz ehrlich, vielen Dank, lieber Freund.\n\nAlso, die Halskette, die Ihr da habt, ist eine meiner edelsten Kreationen, aber es fehlen drei Edelsteine, mit der magische Macht an sie gebunden werden kann. Ich fertigte sie vor geraumer Zeit für einen Paladin an. Er befand sich auf einem selbst auferlegten Kreuzzug, um die \"böse Verseuchung\" auszumerzen, die eine Ausgrabungsstätte namens Uldaman im Ödland befallen hatte.\n\nAber der Paladin starb in Uldaman und das war erst der Anfang meines Elends." }, enUS = { progress = "Have you got the five silver bars I asked for?  I will share my sad tale of woe with you concerning the necklace you now possess... but only after I get those bars!  Please, help a gnome out, won't ya?", completion = "You're all right in my book; I don't care what everyone else has been saying... I kid, I kid!  Seriously, thank you my friend.\n\nNow, the necklace you have is one of my finest creations, but it is missing three gems that help bind magic power to it.  I crafted it for a paladin some time ago.  He was on a self-appointed quest to clear out the \"evil taint\" present at an excavation site in the Badlands called Uldaman.\n\nWell... that paladin died in Uldaman, and that was just the beginning of my woes." } })
apply(2201, { "classic", "forever" }, { deDE = { progress = "Talvashs Bild nimmt in dem Wasser der Wahrsageschale Kontur an.\n\n\"Hey, Ihr lebt noch! Habt Ihr die Edelsteine gefunden? Könnt Ihr wirklich meinen guten Ruf retten, so wie ich das erhofft habe? Bitte sagt mir, dass Ihr keine Ladung der Phiole verbraucht habt, um mal schnell hallo zu sagen. Diese Dinge sind nicht billig und ich pfeife finanziell gesehen jetzt schon auf dem letzten Loch.\"", completion = "Ja, das sind tatsächlich die drei Edelsteine. Sehr gut! Leider ist Eure Arbeit aber damit noch nicht ganz getan.\n\nNein, ich versuche nicht, Euch über den Tisch zu ziehen. Typisch {class}! Hier geht es um die Herstellung magischen Schmucks - und zwar Schmuck von einer Güte, wie Talvash del Kissel ihn herstellt! Da braucht man schon eine starke Kraftquelle, um dem Ganzen den nötigen Bumms zu geben. Und diese Halskette hat absolut keinen Bumms mehr." }, enUS = { progress = "Talvash's image comes into focus from the waters of the scrying bowl.\n\n\"Wow, you're still alive!  Did you manage to find the gems?  Are you truly the savior of my reputation I have hoped for?  Please tell me you didn't waste a charge on the phial just to chat; those things are NOT cheap, and I'm already in dire financial straits.\"", completion = "Yep, those indeed are the three gems.  Good job!  Unfortunately, your work isn't quite over just yet.\n\nNo, I'm not trying to pull a fast one here, silly {class}.  This is about making magic jewelry - Talvash del Kissel quality-level jewelry!  You need a strong power source to give it some oomph.  Well, that necklace has no more oomph to give." } })
apply(2202, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die magenta Funguskappen bekommen, die ich für meine alchimistische Arbeit benötige? Keine Kappen - keine Belohnung!", completion = "Gut gemacht, {name}, Ihr habt mir Euren Wert abermals bewiesen! Es wird interessant sein, die Funguskappen zu studieren, da könnt Ihr drauf wetten.\n\nAber nun, wie versprochen: Genießt eine Kostprobe eines besonders wirksamen Regenerierungsgebräus, das ich normalerweise nur für den Eigengebrauch herstelle ...\n\nFalls Ihr in der Alchimie bewandert seid, dann können wir vielleicht noch weitere Geschäfte miteinander machen. Aber wie dem auch sei, habt Dank für Eure Unterstützung!" }, enUS = { progress = "Have you obtained the magenta fungus caps I need for my alchemical work?  No caps - no reward!", completion = "Well done {name}, you've proven your worth once again!  The caps will be an interesting study, you betcha.\n\nAnd now, as promised, enjoy a taste of one of my more potent restorative brews from my personal stock...\n\nIf you are a skilled alchemist, then perhaps we might have some additional business to conduct.  Regardless, I thank you for your assistance!" } })
apply(2203, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Gefäße benutzt, um das Blut versengter Wächtergroßdrachen zu beschaffen, das ich brauche? Ja, ich weiß, es ist eine gefährliche Aufgabe... aber das Rezept für mein Regenerierungsgebräu ist der Lohn Eures Erfolges. Von nichts kommt eben nichts, mein Freund... Von nichts kommt nichts...", completion = "Ich grüße Euch von Alchimist zu Alchimist. Hier, nehmt das Rezept und reiht es Eurem Wissen ein. Möge es Euch denselben Erfolg und die Belohnungen bringen wie mir im Lauf der Jahre." }, enUS = { progress = "Have you used the vessels to get me the scorched guardian dragon blood I need?  Yes, I know it is a dangerous task... but the recipe for my restorative brew awaits your success.  Risk and reward, my friend... risk and reward...", completion = "From one alchemist to another, I salute you.  Here, take this recipe and commit it to your knowledge.  May it bring you the success and rewards that it has brought me over the years." } })
apply(2204, { "classic", "forever" }, { deDE = { progress = "Ihr habt Euch nicht mal die Zeit genommen, Euch etwas frisch zu machen, nachdem Ihr Uldaman verlassen hattet, oder? Ihr seid direkt hierher gekommen und pfeift auf die Kerkerdüfte, die Euch anhängen. Na, dann hoffen wir mal, dass dieser Besuch wirklich nur ein geruchvoller ist und nicht ein erfolgloser noch dazu.\n\nHabt Ihr die Kraftquelle für die Halskette?", completion = "Da soll mich doch... Ich freue mich wirklich sehr, Euch und diese Kraftquelle in einem Stück zu sehen! Es dauert einen Moment, bis ich die Kraftquelle auf magische Weise mit der Kette verschmolzen habe, jetzt, da die Edelsteine wieder angebracht sind. Sobald das aber passiert ist, gehört die Halskette Euch!\n\nIhr seid bestimmt aufgeregt, oder? Schon ganz kribbelig vor Erwartung? Wo hab ich denn bloß diesen Zauberfokus hingelegt..." }, enUS = { progress = "You didn't even stop to tidy yourself up after leaving Uldaman, did you.  You just came straight here, lingering dungeon odors be damned.  Well, let's hope this visit is merely an odiferous one, and not a useless one to boot.\n\nDo you have the power source for the necklace?", completion = "Well I'll be - I sure am glad to see you and this power source in one piece.  It will take me a moment to magically fuse the power source with the necklace now that the gems have been reunited with it.  Once it is done, however, the necklace will be yours!\n\nYou're excited, aren't you?  All tingly with anticipation?  Now where did I put that spell focus at..." } })
apply(2206, { "classic", "forever" }, { deDE = { progress = "Eure Sterblichkeit schwindet mit jedem Moment, den Ihr in der Kaserne verweilt, {class}.", completion = "Ich bin erstaunt... Erstaunt, dass Keryn endlich einen Rekruten gefunden hat, der das Zeug zu einem anständigen Schurken besitzt. Nehmt diese Klinge, {name}. Es kommt der Tag, da wird man Euch bitten, dem SI:7 zu dienen. Perfektioniert Eure Fähigkeiten, haltet die Augen offen und diese Klinge scharf.\n\nIhr werdet uns nicht kommen sehen, aber Ihr werdet es spüren, wenn wir da sind..." }, enUS = { progress = "Your mortality wanes with every moment you waste loitering in the barracks, {class}.", completion = "I am astonished... Astonished that Keryn finally found a recruit that could possibly have the makings of a proper {class}. Take this blade, {name}. A day will come when you will be called upon again to serve the SI:7. Hone your skills, keep your eyes open and that blade sharp.\n\nYou won't see us coming but you'll feel it when we get there..." } })
apply(2218, { "classic", "forever" }, { deDE = { completion = "Ihr glaubt also, Ihr seid ein Halunke? Dem es vorbestimmt ist, einer von Blackbeards Auserwählten zu sein - ein Offizier des Verborgenen Kreises?\n\nNur jemand, der gar nichts taugt, hätte so eine hohe Meinung von sich.\n\nGenau nach so einem suchen wir! Willkommen an Bord, {name}!" }, enUS = { completion = "So ye think yer a right scoundrel? Destined to be one o' Blackbeard's chosen few - an officer o' the Hidden Circle?\n\nOnly a good fer nothin' scallywag would think so highly o' hisself.\n\nThat's exactly what we be lookin' fer! Welcome aboard, {name}!" } })
apply(2238, { "classic", "forever" }, { deDE = { completion = "Psst! Leise, elender Narr! Sonst werden sie uns noch hören." }, enUS = { completion = "Shhhh! Keep it down you daft fool. They'll hear us." } })
apply(2239, { "classic", "forever" }, { deDE = { progress = "Hat Euch der Gestank des Lepragnoms gefallen? Ich frage nur, weil Ihr so ein irres Lächeln im Gesicht habt.\n\nWelche Neuigkeiten bringt Ihr von Onin?", completion = "Langer Weg? Im Namen meines eigenen Barts!\n\nDas habt Ihr gut gemacht, {name}. Nehmt diesen Dolch und fort mit Euch. Der Kreis ruft Euch wieder, wenn Stufe drei in Angriff genommen werden kann.\n\nWas Stufe drei ist? Die kommt gleich nach Stufe zwei - dass ich Euch meine Stiefelspitze in den Hintern ramme.\n\nInteressiert?" }, enUS = { progress = "Did ye enjoy the stench of leper gnome? I only ask because ye got a crazy smile on yer face.\n\nWhat news do ye bring from Onin?", completion = "Long route? In the name o' me own beard!\n\nYe done good, {name}. Take this dagger and be gone with ye. The Circle will call upon ye again when step three be ready to be set into motion.\n\nWhat's step three? It comes right after step two - me putting me boot up yer backside.\n\nInterested?" } })
apply(2240, { "classic", "forever" }, { deDE = { completion = "Ihr habt die Kammer von Khaz'mul gesehen? Erstaunlich! Baelog war sich sicher, dass es sie geben müsse, aber ich muss gestehen, dass ich so meine Zweifel hatte.\n\nDanke, {name}. Mit etwas Glück wird Euer Fund unsere Anführer dazu bewegen, ihre Anstrengungen zur Wiedereroberung von Uldaman zu verstärken. Und sollte es jemals wieder unter die Kontrolle von Ironforge fallen, dann sind die Geheimnisse der Kammer von Khaz'mul unser!" }, enUS = { completion = "You have seen the Chamber of Khaz'mul?  Amazing!  Baelog was sure it existed, but I must admit that I had my doubts.\n\nThank you, {name}.  With luck your finding will incite our leaders to renew their efforts to retake Uldaman.  And if it is ever again under Ironforge control, then the secrets of the Chamber of Khaz'mul will be ours!" } })
apply(2241, { "classic", "forever" }, { deDE = { progress = "Oh, ist das nicht herrlich. Ihr habt Blumen für Euer eigenes Begräbnis mitgebracht.", completion = "Hätte ich jede Blume aufgehoben, die mir dieser Trottel Jannok schickte, könnte ich einen Blumenladen eröffnen. Allerdings könnte sich Jannoks neuester Kurier als nützlich erweisen.\n\nSeid Ihr an Arbeit interessiert, {class}?" }, enUS = { progress = "Oh, isn't this wonderful. You've brought flowers for your own funeral.", completion = "Had I saved every flower that dolt, Jannok, had sent me, I would have had the means to open a shop. Regardless, it seems as if Jannok's latest courier may prove to be useful.\n\nInterested in some work, {class}?" } })
apply(2242, { "classic", "forever" }, { deDE = { progress = "Habt Ihr etwas von Sethir dem Urtum zu berichten, {name}?", completion = "Das sind schlimme Neuigkeiten, {name}. Es scheint, als würde die Erkrankung, die die Wälder und Flüsse von Dunkelküste besudelt hat, auf unsere Heimat übergreifen.\n\nIhr habt uns gute Dienste geleistet, aber hier könnt Ihr nichts mehr tun. Nehmt diese Klinge als Lohn für Eure Dienste für Teldrassil." }, enUS = { progress = "Have you anything to report from Sethir the Ancient, {name}?", completion = "This is grim news, {name}. It would seem that the sickness which has gripped the forests and rivers of Darkshore has begun to taint our home.\n\nYou have served us well, but there is nothing more you can do here. Take this blade as a reward for your service to Teldrassil." } })
apply(2258, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Sachen schon, die ich brauche? Ihr werdet nur bezahlt, wenn Ihr mir diese Reagenzien bringt.", completion = "Ah, gut gemacht! Damit sollte ich eine Weile hinkommen. Hier ist Eure versprochene Bezahlung.\n\nFalls Ihr interessiert seid: Es gibt noch ein paar Reagenzien, die ich brauchen könnte. Die findet man allerdings nur in den Tiefen der Ausgrabung von Uldaman. Sie werden nicht leicht zu beschaffen sein, aber wenn Ihr mir nochmals helfen wollt, soll es sich für Euch lohnen.\n\nVielleicht etwas mehr als nur glänzende Münzen, hm?" }, enUS = { progress = "Have you gotten the things I need yet?  You won't get paid unless you bring me those reagents.", completion = "Ah, well done!  These should last me for a little while, at least.  Here is your pay as promised.\n\nIf you're interested, I have some more reagents I could use.  These, however, are only found in the depths of the Uldaman excavation.  They will not be easy to get, but I will make it worth your while if you are interested in helping me again.\n\nPerhaps something more than some shiny coins, yes?" } })
apply(2259, { "classic", "forever" }, { deDE = { completion = "Es wird Zeit, loszuziehen, {race} - die Welt wartet." }, enUS = { completion = "It is time to branch out, {race} - the world awaits." } })
apply(2260, { "classic", "forever" }, { deDE = { completion = "Ihr seid dem Ruf des SI:7 gefolgt, {name}, und seid von fernen Ufern angereist, um für uns zu arbeiten. Aber es gibt viel zu lernen." }, enUS = { completion = "You have answered SI:7's calling, {name} and journeyed from distant shores to join our ranks, however, there is much for you to learn." } })
apply(2278, { "classic", "forever" }, { deDE = { progress = "Die Stimme des Steinbeobachters scheint in jeder Faser Eures Körpers widerzuhallen:\n\n\"Ihr müsst zunächst den Datenaufnahmevoraussetzungen der Scheiben von Norgannon genügen. Sobald Ihr diese Bedingung erfüllt habt, wird es Euch erlaubt werden, eine tragbare Version der hier aufbewahrten Daten an Euch zu nehmen. Bitte stellt erst sicher, dass Ihr die Informationen in diesem Datenspeicher wirklich alle erkundet habt.\"", completion = "Ihr folgt den Anweisungen des Steinbehüters und greift noch einmal auf die Scheiben von Norgannon zu, nachdem Ihr jetzt die Geschichte der Irdenen, der Troggs und der Zwerge kennt. Aus dem Inneren der Scheiben ertönt ein kurzes, fast unhörbares Summen. Dann spricht der Steinbeobachter erneut:\n\n\"Die Scheiben sind jetzt synthetisiert.\" Greift noch einmal auf die Scheiben von Norgannon zu, um Euer persönliches Exemplar zu erhalten.\"" }, enUS = { progress = "The voice of the stone watcher seems to resonate within your very inner being:\n\n\"You must first satisfy the data assimilation prerequisite of Discs of Norgannon; once you fulfill this requirement, you will then be permitted to obtain a portable version of the stored data.  Please be sure you have fully explored the information within this repository first.\"", completion = "Following the instructions of the stone watcher, you once again access the Discs of Norgannon now that you have learned about the history of the Earthen, the troggs, and the dwarves.  A faint, brief hum is heard from within the discs.  The stone watcher then speaks:\n\n\"The discs have now been synthesized.  Access the Discs of Norgannon once more to receive your personal copy.\"" } })
apply(2279, { "classic", "forever" }, { deDE = { progress = "Ja, kann ich Euch behilflich sein? Ich kann Euch versichern, dass ich zurzeit äußerst beschäftigt bin. Wenn es sich jedoch um eine Angelegenheit von großer Wichtigkeit für die Forscherliga handelt, dann bin ich ganz Ohr!", completion = "Was habt Ihr da... ach du liebe Güte. Das habt Ihr wo gefunden?\n\nNein, wirklich?\n\nIhr habt mir wem worüber gesprochen?\n\nNEIN, WIRKLICH?\n\nMein Lieber, Ihr habt gerade den archäologischen Fund des Jahres gemacht! Aber, bei den Göttern, was rede ich da, {class}, das ist der Fund des Jahrhunderts! Wenn diese Scheiben das sind, wofür ich sie halte, dann könnte das genau der Schlüssel sein, nach dem wir schon so lange suchen! Das hier könnte tatsächlich ein für alle Mal und unwiderlegbar beweisen, dass die Erschaffung der Zwerge durch Zauberkraft kein Wunschdenken, sondern die Wahrheit ist!" }, enUS = { progress = "Yes, may I help you with something?  I assure you I am a very busy right now.  If it is grave importance to the Explorers' League, however, then I am all ears!", completion = "What do you have there... oh my.  You found this where?\n\nNo, really?\n\nYou spoke to whom about what?\n\nNO, REALLY?!\n\nMy fine {class}, you may have just made the archaeological find of the year!  By the Gods who am I kidding, the find of the century!  If these discs are what I think them to be, then this could be the very key we have been looking for!  This may well prove outright once and for all the legitimacy of the Dwarves' enchanted creation!" } })
apply(2280, { "classic", "forever" }, { deDE = { progress = "Ja, Jungchen, ich sehe, wie Ihr mein Zelt betretet: mit Schwung in Eurem Schritt... mit Entschlossenheit in Euren Absichten. Ihr sucht meinen Rat in einer Angelegenheit von höchster Wichtigkeit für die Horde? Ist Euch vielleicht ein Geheimnis des Universums offenbart worden, das Ihr mit mir teilen möchtet?", completion = "Was haben wir denn hier?\n\nIch bin beeindruckt! Drei Scheiben, in denen ich Geheimnisse spüren kann, die die Erde zu viele Jahre lang in ihrem Inneren verborgen hat. Es war sehr klug von Euch, sie zu mir zu bringen." }, enUS = { progress = "Yes young one, I see you marching into my tent with intensity in your stride... with determination in your purpose.  You seek my counsel is some matter of grave importance to the Horde?  Perhaps you wish a mystery of the universe revealed to you?", completion = "What are these here then?\n\nImpressive, young one!  These discs, in them I sense secrets that the earth has held on to tightly for many years.  You were very wise to bring them here to me." } })
apply(2281, { "classic", "forever" }, { deDE = { completion = "Eure Finger sind also ein wenig plump, hm? Keine Bange, {name}, ich habe schon mehr nutzlose Diebe als Euch zu tüchtigen Schurken gemacht." }, enUS = { completion = "Ah, so your fingers are a little fat, eh? Don't worry, {name}, I've turned more useless thieves than you into accomplished rogues." } })
apply(2282, { "classic", "forever" }, { deDE = { progress = "Habe ich vergessen, die Orcs zu erwähnen?\n\nIch habe gehört, dass sie da oben bei der Mühle herumschnüffeln.", completion = "Ihr habt sie aufbekommen? Gute Arbeit, {name}.\n\nWenn Ihr jetzt sterbt, sind wir wenigstens sicher, dass es an Eurer eigenen Dummheit lag, nicht an Eurer Unerfahrenheit." }, enUS = { progress = "Did I forget to mention the orcs?\n\nI hear they have been nosing around up by the mill.", completion = "Cracked it open, did you? Nice work, {name}.\n\nIf you die now, we can rest easy knowing it was due to your own stupidity and not inexperience." } })
apply(2283, { "classic", "forever" }, { deDE = { progress = "Und, habt Ihr die Halskette? Ihr kriegt keinen müden Kupferpfennig von uns, wenn Ihr die Halskette nicht habt!", completion = "Aaaah, geborgenes Gut! Ich kann die Halskette schon riechen. Dann wollen wir uns die Schönheit mal anschauen...\n\nHe, was für ein Spiel wollt Ihr hier spielen? Bei dieser Halskette fehlen die Edelsteine! Habt Ihr etwa gedacht, das würde uns nicht auffallen? Sogar Malton würde es auffallen, dass die Edelsteine weg sind.\n\nNa, vielleicht habt Ihr sie nicht gestohlen... aber ohne die Edelsteine ist die Halskette wertlos! Euer Job ist noch nicht erledigt, noch lange nicht!" }, enUS = { progress = "Well, do you have the necklace?  You won't see a copper from us if you don't have that necklace!", completion = "Mmmm salvage!  I can smell the necklace from here.  Now let's look at that beauty...\n\nHey, what do you think you're trying to do here?  This necklace is missing the gems!  You think we wouldn't notice?  Even Malton could see that the gems are gone.\n\nWell, maybe you didn't steal them... but this necklace is worthless without those gems!  Your job isn't done here yet, not by a long shot!" } })
apply(2284, { "classic", "forever" }, { deDE = { completion = "Es scheint, als hättet Ihr die Überreste des Paladins gefunden, den Dran erwähnte. Als Ihr die Überreste durchsucht, entdeckt Ihr etwas, das sein Tagebuch zu sein scheint. Das Buch ist in keinem guten Zustand, da der größte Teil des Textes darin von getrocknetem Blut unleserlich gemacht wird. Und was Ihr davon lesen könnt, ist nicht zu entziffern, denn soweit Ihr das beurteilen könnt, ist es in der Menschensprache geschrieben.\n\nIhr müsst das Buch übersetzen lassen, wenn Ihr irgendwelches Wissen daraus ziehen wollt." }, enUS = { completion = "You seem to have found the remains of the paladin that Dran had mentioned from before.  Searching the remains uncovers what would appear to be his journal.  The book is in poor condition, as dried blood has stained most of the text in the book.  What you can read, however, is gibberish; it is written in the native tongue of the humans, to the best of your knowledge.\n\nYou will need the book translated if you are to glean any knowledge from it." } })
apply(2298, { "classic", "forever" }, { deDE = { completion = "Es ist immer schön, einen von Hulfdans Schurken in unseren Reihen zu haben!" }, enUS = { completion = "It's always good to have one of Hulfdan's rogues among our ranks!" } })
apply(2300, { "classic", "forever" }, { deDE = { completion = "Seid Ihr bereit zu arbeiten oder müsst Ihr ein Nickerchen machen, ehe wir anfangen?" }, enUS = { completion = "Are you ready to get to work or do you need to take a nap before we get started?" } })
apply(2338, { "classic", "forever" }, { deDE = { progress = "Ihr habt es Euch überlegt, ja? Ihr seid ein schlauer {class}, wenn Ihr dieses Angebot annehmt - Ihr und ich werden beide bekommen, was wir wollen, und 'Droffers und Sohn Bergungen' werden denken, dass sie bekommen, was sie wollen.", completion = "Ihr erkennt ein gutes Angebot, wenn Ihr eines bekommt - ich wusste, dass ich auf Euch zählen kann.\n\nEs dauert nur einen Moment. Ich wirke einen Zauber, der die Menschensprache schnell in etwas übersetzt, das Ihr verstehen könnt. Ich bin ein Troll, der sein Wort hält - Ihr könnt jeden in der Horde auf Jarkal Mossmeld ansprechen. Also, dann wollen wir mal anfangen ..." }, enUS = { progress = "You've thought about it, yes?  You're a smart {class} if you take this deal - you and I will get what we both want, and Droffers and Son Salvage will think they're getting what they want.", completion = "You know a good deal when you see one - I knew I could count on you.\n\nIt will be just a moment while I cast a spell to quickly translate the human tongue into a form you will understand.  I am a troll of my word; ask anyone in the Horde about Jarkal Mossmeld.  Now, let's get this started..." } })
apply(2339, { "classic", "forever" }, { deDE = { progress = "Euch steht ein weiterer Ausflug in die Tiefen von Uldaman bevor, wenn Ihr nicht die Edelsteine sowie eine Kraftquelle habt, die die magische Kraft wieder zurück in die Halskette kanalisieren kann.", completion = "Sehr gut, {class}. Jetzt wird sich unser kleines Täuschungsmanöver wunderbar auszahlen. Mit der Halskette selbst bin ich fertig und ich bin mir sicher, dass ich den Herstellungsprozess jederzeit wiederholen kann.\n\nDoch zunächst spreche ich noch eine eigens dafür vorbereitete Zauberformel, um die Edelsteine zu analysieren, ehe Ihr sie und die Halskette nach Orgrimmar zurückbringt. Das dauert auch nur einen kleinen Moment." }, enUS = { progress = "You've got another trip into the depths of Uldaman in store for yourself if you don't have the gems and a power source capable of channeling magical power back into the necklace.\n\nYou'll be getting the gems back to deliver to the goons in Orgrimmar; I will be keeping the power source, since it will be the thing that will make the necklace work in the first place...", completion = "Very well done, {class}.  Now the fruits of our redirection will pay themselves out handsomely.  I'm finished with the necklace itself, and I am confident I can duplicate the construction process consistently.\n\nBut first, I will use a specially prepared incantation to quickly analyze those gems before you take them and the necklace back to Orgrimmar.  This will take just a brief moment to do." } })
apply(2340, { "classic", "forever" }, { deDE = { completion = "Jawoll, alles da. Sagt mal, macht es Euch was aus, wenn wir auch den Beutel behalten? Nein? Danke, ich weiß das zu schätzen! Haha!\n\nDiese Halskette wird unser bester Fang bisher sein! Aber macht Euch nichts draus. Die Kette würde Euch ja ohnehin nicht passen. Haha!\n\nEin Geschäft ist ein Geschäft, also habt Ihr hier Euren Lohn für die Bergung. Fürs Erste ist unser Handel abgeschlossen, aber kommt ruhig später wieder, dann haben wir vielleicht wieder Arbeit für Euch. Aber bis dahin verschwindet!" }, enUS = { completion = "Yep, it's all here.  Say, mind if we keep the bag too?  No?  Thanks, appreciate it!  Har!\n\nThis necklace will be our greatest haul yet!  Don't feel too bad though; I'm sure the necklace wouldn't fit you anyway.  Har again!\n\nA deal is a deal, so here's your fee for the salvage.  Our business is done here for now; check back later to see if we have more work.  Until then, beat it!" } })
apply(2341, { "classic", "forever" }, { deDE = { completion = "Die Kraftquelle, die Ihr mir gegeben habt, hat alle meine Erwartungen übertroffen. Ich konnte sowohl für Euch als auch für mich selbst eine Halskette herstellen und ich habe noch genug übrig, um mindestens drei weitere anfertigen zu können. Sie werden nicht wenig Geld einbringen und 'Droffers und Sohn Bergungen' sind so klug wie zuvor.\n\nBitte sehr, mein Bester. Ich danke Euch von Herzen für Eure ausgezeichnete Arbeit ... Hier habt Ihr etwas ganz Besonderes als Lohn für Eure Mühen." }, enUS = { completion = "The power source you gave me exceeded every expectation I had for it.  I was able to make both you and me a necklace, and I have enough left over to make at least three more.  They will fetch quite the fee, with Droffers and Son Salvage none the wiser.\n\nHere you go, my friend.  I give you my thanks on a splendid job... and something quite special for your trouble." } })
apply(2342, { "classic", "forever" }, { deDE = { progress = "Das Kehren nimmt nie ein Ende... Diese Fledermäuse bringen ihre Verachtung für mich und meinen Besen wirklich höchst produktiv zum Ausdruck. Bitte sagt mir, dass Ihr den Schatz meiner Familie wiedererlangt habt! Ich habe Euch all mein Silber angeboten - reicht das nicht?!", completion = "Endlich - ein Besen, der eines Garretts würdig ist. Ihr seid verdammt noch mal jedes Silberstück wert, das ich Euch bezahlt habe!\n\nHabt Ihr das gehört, ihr elenden Fledermäuse? Ich halte jetzt die Lieblingswaffe der Familie Garrett in Händen! Erzittert, ihr Fledermäuse, erzittert!" }, enUS = { progress = "The sweeping never ends... these bats are prolific in their mockery of me and my broom.  Please tell me you've reclaimed my family's treasure!  I've offered you my silver - is that not enough?!", completion = "At last - a broom worthy of a Garrett.  You're bloody well worth every silver I spent on you, I say!\n\nDo you hear me, foul bats?  I now wield the Garrett family weapon of choice!  Tremble, bats, tremble!!" } })
apply(2359, { "classic", "forever" }, { deDE = { progress = "Gibt es etwas Neues von Agentin Kearnen?", completion = "Das erklärt die Anwesenheit der Defiasdrohnen, die Ihr und Kearnen vor dem Turm gesehen habt, {name}. Es würde auch erklären, was die Venture Company mit den Defias zu tun hat und was es mit den seltsamen Lieferungen aus dem Dämmerwald auf sich hat.\n\nIn diesem Buch heißt es, dass die Trolle der Zanzil im Schlingendorntal einen Weg gefunden haben, mit bestimmten Tränken die Toten zu erwecken... oder, um genau zu sein, mit Gift.\n\nOhne ein umfangreiches Wissen über Gifte habt Ihr für den SI:7 keinen großen Nutzen, {name} - vor allem nicht ohne das Wissen darüber, wie man mit einem einfachen Rezept auf Wunsch Untote erschaffen kann." }, enUS = { progress = "Any news from Agent Kearnen?", completion = "This would explain the Defias drones you and Kearnen saw outside of the tower, {name}. It would also explain the Venture Company's involvement with the Defias and the strange shipments out of Duskwood.\n\nAccording to this book, the Zanzil trolls in Stranglethorn have discovered a way to raise the dead through potions... or to be more specific: poison.\n\nYou'll be of no use to SI:7 without a firm understanding of poisons, {name} -- especially with the recipe to create undeath at our fingertips." } })
apply(2360, { "classic", "forever" }, { deDE = { completion = "Mathias hat also endlich einen weiteren Agenten zu meiner Unterstützung geschickt, hm? Na, ich hoffe, er ist auf schlechte Nachrichten gefasst." }, enUS = { completion = "Mathias finally sent another agent to back me up, eh? Well I hope he's ready to hear some bad news." } })
apply(2378, { "classic", "forever" }, { deDE = { completion = "Ihr seid also das, was unsere mächtigen Verbündeten zu Shenthul schicken? Wie langweilig..." }, enUS = { completion = "So, you are what our mighty allies have sent Shenthul? How uninspiring...." } })
apply(2381, { "classic", "forever" }, { deDE = { progress = "Na, wenigstens habt Ihr noch alle Eure Körperteile beisammen. Habt Ihr den Schatz gefunden?", completion = "Unglaublich! Unwahrscheinlich! Einfach erstaunlich! Ihr habt Talent, {name}. Entweder das oder Ihr habt ein Glück wie niemand sonst auf der Welt!\n\nHier ist Euer Anteil an der ganzen Sache. Ich bin sicher, Ihr könnt das alles besser verwenden als ich." }, enUS = { progress = "Well, at least you still have all of your body parts. Did you find the treasure?", completion = "Incredible! Improbable! Simply amazing! You've got talent, {name}. Either that or you're the luckiest man alive!\n\nHere's your cut of the action. I'm sure you would make better use of this stuff than I could." } })
apply(2382, { "classic", "forever" }, { deDE = { completion = "Noch einer? Die letzten fünf, die dieser verrückte Troll mir geschickt hat, endeten als Haifutter. Wollen wir hoffen, dass es Euch etwas besser ergeht, wie?" }, enUS = { completion = "Another one? The last five that crazy troll sent me ended up as shark food. Let's hope you fare a little better, eh?" } })
apply(2383, { "classic", "forever" }, { deDE = { progress = "Was habt Ihr denn da? Ein Pergament? Ich hoffe, Ihr seid kein Gelehrter...", completion = "Ach, da ist ja mein Pergament. Ich habe gehört, dass Ihr ins Tal kommen würdet, {name}. Freut mich zu sehen, dass Ihr es geschafft habt - hoffen wir nur, dass Ihr die Prüfungen überlebt, die vor Euch liegen. Wie ich bereits sagte: Wenn Eure Macht wächst, kommt zu mir - ich werde tun, was ich kann, um Euch weiter in der Kunst eines Kriegers auszubilden.\n\nViel Glück, {name}. Ihr könnt jederzeit wieder zu mir kommen, wenn Ihr Euch bereit fühlt." }, enUS = { progress = "What's that you have there?  A parchment?  You're not a scholar, I hope...", completion = "Ah, that's my parchment.  I heard you'd be coming to the Valley, {name}.  I'm glad to see you made it--let's hope you survive the trials ahead. Like I said, as you gain in power, come to me--I will do what I can to train you in the ways of the {class}.\n\nGood luck, {name}, and return to me whenever you feel ready." } })
apply(2398, { "classic", "forever" }, { deDE = { completion = "Wurde auch Zeit, dass ihr auftaucht! Ich hätte fast meine Wette mit Olaf verloren!\n\nEr hat gewettet, dass ihm sein Bart bis zu den Knien wachsen würde, ehe ihm wieder ein {race} vor die Augen kommen würde. Aber jetzt seid Ihr hier, und wie Ihr sehen könnt, fehlen Olafs Bart noch ein paar Zoll.\n\nDanke, {name}. Ich werde den Gewinn mit Euch teilen." }, enUS = { completion = "It's about time you showed up!  I was in danger of losing a bet with Olaf!\n\nHe wagered that his beard would grow to his knees before he saw another living {race}.  Well here you are, and as you can see Olaf's beard has a few more inches to go.\n\nThanks, {name}.  I'll split the winnings with you." } })
apply(2418, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Kraftsteine, {name}? Ich habe hier ein Robotnagetier, das eine Stromquelle braucht...", completion = "Oh prima, Ihr habt welche gefunden! Vielen Dank, {name}. Ihr seid der verlässlichste {race}, den ich je getroffen habe!\n\nIch kann es kaum erwarten, sie an einigen der Geräte auszuprobieren, an denen ich rumgebastelt habe. Ich wette, dass unter den richtigen Umständen ein Gerät, das mit so einem Stein angetrieben wird, läuft und läuft und läuft ..." }, enUS = { progress = "Do you have the power stones, {name}?  I have a robotic rodent that needs a power supply...", completion = "That's great, you found some!  Thanks a lot, {name}.  You're the most dependable {race} I've met!\n\nI can't wait to try these on some devices I've been tinkering with.  I bet that, under the right circumstances, devices powered with these stones will keep going, and going, and going..." } })
apply(2438, { "classic", "forever" }, { deDE = { progress = "Bitte sputet Euch. Ich kann nur hoffen, dass mein smaragdgrüner Traumfänger von den Furbolgs nicht beschädigt wurde.\n\nHabt Ihr ihn schon zurückgeholt, {name}?", completion = "Mein smaragdgrüner Traumfänger ist mir äußerst wichtig. Er ist ein Geschenk, das nicht jedem zuteil wird. Danke, dass Ihr ihn zurückgebracht habt, {name}." }, enUS = { progress = "Please move swiftly. I can only hope that my emerald dreamcatcher has been unharmed by the furbolg.\n\nHave you recovered it yet, {name}?", completion = "My emerald dreamcatcher is of great importance to me. It is a gift only given to few. Thank you for returning it, {name}." } })
apply(2439, { "classic", "forever" }, { deDE = { progress = "Willkommen im Gewölbe von Ironforge, {name}. Was kann ich heute für Euch tun?", completion = "Ah ja, ein Gutschein von der Forscherliga... und recht wertvoll, kann man sagen.\n\nEntsprechend dem Auftrag der Forscherliga kann ich Euch bei Eurer Belohnung die Wahl zwischen diversen aus ihrem Gewölbe stammenden Dingen lassen. Zum einen sollt Ihr diesen Gegenstand erhalten, und zum anderen dürft Ihr Euch entscheiden, ob Ihr fünf überragende Heiltränke oder fünf große Manatränke haben möchtet." }, enUS = { progress = "Welcome to the Vault of Ironforge, {name}.  What may I do for you today?", completion = "As yes, a voucher from the Explorers' League... and quite the valuable one, might I add.\n\nThe Explorers' League lends me the authority to offer you a choice in your compensation directly from their vault.  You are to receive this item, and you may choose between five superior healing potions or five greater mana potions as your reward." } })
apply(2440, { "classic", "forever" }, { deDE = { progress = "Grüße, {class}! Seid Ihr hier, weil Ihr eine Ausbildung in Alchimie wünscht, oder aus einem anderen Grund?", completion = "Na, {name}, Ihr müsst Sage Truthseeker ja eine große Freude gemacht haben, dass er Euch diesen Gegenstand überlässt. Außerdem sollt Ihr zur Belohnung aus seinem Vorrat an Tränken auswählen dürfen: entweder 5 überragende Heiltränke oder 5 große Manatränke." }, enUS = { progress = "Greetings, {class}!  Are you here for alchemy training, or perhaps something else?", completion = "Well {name}, you must have pleased Sage Truthseeker greatly for him to give you this item.  You are also to be granted a gift from his cache of potions; you may choose between 5 superior healing potions or 5 greater mana potions as your reward." } })
apply(2459, { "classic", "forever" }, { deDE = { progress = "Ferocitas und die Knarzklauenmystiker müssen mir zurückgeben, was mir gehört. Bitte holt den Smaragd zurück, damit ich meinen smaragdgrünen Traumfänger reparieren kann.", completion = "Jetzt kann ich meinen Traumfänger reparieren. Danke, {name}." }, enUS = { progress = "Ferocitas and the Gnarlpine mystics must return what is mine.  Please retrieve the emerald so that I may repair my emerald dreamcatcher.", completion = "Now I can repair my dreamcatcher.  Thank you, {name}." } })
apply(2460, { "classic", "forever" }, { deDE = { progress = "Übung macht den Meister!", completion = "Gut gemacht, {name}. Jetzt kann es weitergehen." }, enUS = { progress = "Practice!", completion = "Well done, {name}. You are now ready to proceed." } })
apply(2478, { "classic", "forever" }, { deDE = { progress = "Was gibt es zu berichten, {name}?", completion = "Der arme Fizzule. Er war ein guter Agent, einer unserer besten. Doch das ist leider der Preis, den wir zahlen müssen, {name}. Ein Außenagent der Shattered-Hand zu sein, ist sehr gefährlich.\n\nIhr habt Eure Befehle gut ausgeführt, {class}. Es wäre ein Jammer, wenn Ihr nicht überleben würdet, um uns erneut zu dienen." }, enUS = { progress = "What have you to report, {name}?", completion = "Poor Fizzule, he was a good agent -- one of our best. Alas, it is the price we pay, {name}. Being a field agent of the Shattered Hand is dangerous work.\n\nYou have performed your duty well, {class}. It would be a shame if you did not live to serve us again." } })
apply(2479, { "classic", "forever" }, { deDE = { progress = "Was haben wir denn hier?", completion = "Ihr seht so herrlich blass aus, {class}. Und was für ein fauliger Duft umgibt Euch da? Ich muss es wissen!" }, enUS = { progress = "What's this???", completion = "You look deliciously pale, {class}. And what is that foul aroma you are giving off? I must know!" } })
apply(2480, { "classic", "forever" }, { deDE = { completion = "Das Heilmittel ist fertig! Trinkt dieses Antitoxin, dann hört der schleichende Wahnsinn auf. Doch gegen den Geruch kann ich nichts tun." }, enUS = { completion = "The cure is ready! Drink this anti-toxin and the creeping madness will stop, however, I will not be able to do anything about the smell." } })
apply(2498, { "classic", "forever" }, { deDE = { completion = "Ah, Rellian hat Euch also geschickt. Es freut mich, dass Ihr so schnell gekommen seid.\n\nIch habe eine ziemlich erschreckende Entdeckung gemacht!" }, enUS = { completion = "Ah, so Rellian sent you to aid me. I am glad you arrived here so soon.\n\nI have discovered something quite disturbing!" } })
apply(2499, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Grimmeiche schon gefunden, {race}?", completion = "Ich wusste doch, dass Ihr bestens in der Lage sein würdet, den See von dieser schrecklichen Bestie zu befreien.\n\nEs ist schon traurig: Einst war Grimmeiche ein großer Anführer unter seinesgleichen... Aber die Verderbnis unterscheidet leider nicht zwischen dem Geringen und dem Edlen.\n\nDie Größe dieses Tumors ist erschreckend. Aber ich muss ihn studieren, um mehr über diese Seuche herauszufinden, von der alle Bäumlinge betroffen sind.\n\nDanke, {name}." }, enUS = { progress = "Have you located Oakenscowl yet, {race}?", completion = "I knew you were more than capable of ridding the lake of that horrible beast.\n\nIt is a distressing situation; Oakenscowl was once a grand leader amongst his kind... but corruption does not discriminate between the lowly and the noble.\n\nThe size of this tumor is quite disturbing, but I must study it to learn more about the disease that upsets the timberling population.\n\nThank you, {name}." } })
apply(2500, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Sachen schon, die ich brauche? Ihr werdet nur bezahlt, wenn Ihr mir diese Reagenzien bringt.", completion = "Ah, gut gemacht, {name}. Das sollte eine Weile reichen. Hier ist Eure Bezahlung, wie versprochen.\n\nFalls Ihr interessiert seid: Es gibt da noch ein paar Reagenzien mehr, die ich brauchen könnte. Die findet man allerdings nur in den Tiefen der Ausgrabungstätte von Uldaman. Sie werden nicht leicht zu beschaffen sein, aber wenn Ihr mir nochmals helfen wollt, soll es sich für Euch lohnen.\n\nVielleicht möchtet Ihr ja etwas mehr als nur glänzende Münzen, hm?" }, enUS = { progress = "Have you gotten the things I need yet?  You won't get paid unless you bring me those reagents.", completion = "Ah, well done {name}.  These should last me for a little while at least.  Here is your pay, as promised.\n\nIf you're interested, I have some more reagents I could use.  These, however, are only found in the depths of the Uldaman excavation.  They will not be easy to get, but I will make it worth your while if you are interested in helping me again.\n\nPerhaps something more than some shiny coins, yes?" } })
apply(2501, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Gefäße benutzt, um das Blut versengter Wächtergroßdrachen zu beschaffen, das ich brauche? Ja, ich weiß, es ist eine gefährliche Aufgabe... aber das Rezept für mein Regenerierungsgebräu ist der Lohn Eures Erfolges. Von nichts kommt eben nichts, mein Freund... Von nichts kommt nichts...", completion = "Ich grüße Euch von Alchimist zu Alchimist. Hier, nehmt das Rezept und reiht es Eurem Wissen ein. Möge es Euch denselben Erfolg und dieselben Belohnungen bringen wie mir im Lauf der Jahre!" }, enUS = { progress = "Have you used the vessels to get me the scorched guardian dragon blood I need?  Yes, I know it is a dangerous task... but the recipe for my restorative brew awaits your success.  Risk and reward, my friend... risk and reward...", completion = "From one alchemist to another, I salute you.  Here, take this recipe and commit it to your knowledge.  May it bring you the success and rewards that it has brought me over the years!" } })
apply(2518, { "classic", "forever" }, { deDE = { progress = "Ich bedauere, dass ich Euch die Aufgabe stellen musste, die ich Euch gestellt habe, aber für Lady Sathrah gibt es keine Hoffnung mehr.\n\nMit den Spinndrüsen wollen wir Elune ein Opfer bringen. Wir hoffen, dass Elune aufgrund dieses Opfers Sathrah segnen wird, damit sie wiedergeboren werden und endlich Frieden finden kann.", completion = "Der Wald trauert um Lady Sathrah, doch es musste getan werden.\n\nDanke, {name}." }, enUS = { progress = "I regret the task that I have asked you to carry out; but Lady Sathrah is beyond hope.\n\nIt is our hope to offer the sacrifice of the spinnerets to Elune. With this sacrifice, Elune will bless Sathrah so that she might be reborn, and at peace.", completion = "The forest mourns for Lady Sathrah, but it was something that had to be done.\n\nThank you, {name}." } })
apply(2519, { "classic", "forever" }, { deDE = { completion = "Schwester Aquinne hat Euch also geschickt?" }, enUS = { completion = "So, Sister Aquinne sent you?" } })
apply(2520, { "classic", "forever" }, { deDE = { progress = "Habt Ihr das Opfer am Brunnen abgelegt, {name}?", completion = "Es stimmt mich traurig, dass wir Lady Sathrah verloren haben, aber nur so kann sie mit erneuertem Geist wiedergeboren werden.\n\nMöge Elune gnädig das Opfer annehmen, das Ihr ihr geweiht habt!" }, enUS = { progress = "Have you placed the sacrifice at the fountain, {name}?", completion = "The loss of Lady Sathrah is distressing, but in this way only may she be reborn with a renewed spirit.\n\nMay Elune willingly accept the sacrifice that you have offered her." } })
apply(2521, { "classic", "forever" }, { deDE = { progress = "Ich habe mein Leben der Suche nach fehlerlosen Draenethystsphären gewidmet. Mein ganzes Leben, {race}!", completion = "Täuschen mich meine Augen? Unmöglich! Wo habt Ihr... Wie...\n\nVielleicht kann jetzt ein neuer Riss geöffnet werden, der es uns ermöglicht, in unsere Heimat zurückzukehren..." }, enUS = { progress = "I have dedicated my life to the search of flawless draenethyst spheres. A lifetime, {race}!", completion = "Do my eyes deceive me? Impossible! Where did you... How...\n\nPerhaps now a rift can be opened, returning us to our homeland." } })
apply(2522, { "classic", "forever" }, { deDE = { progress = "Habt Ihr noch eine fehlerlose Draenethystsphäre gefunden?", completion = "Einfach erstaunlich. Ich hatte so meine Zweifel, dass Ihr noch eine Sphäre finden würdet, aber hier ist sie und pulsiert in meinen Händen.\n\nGut gemacht, {name}!\n\nSolltet Ihr noch weitere Sphären finden - wobei ich glaube, dass das unmöglich ist -, dann bringt sie mir und ich werde Euch erneut belohnen." }, enUS = { progress = "Have you found another flawless draenethyst sphere?", completion = "Simply amazing. I had doubted that you could find another sphere, yet here it is, pulsating in my hands.\n\nWell done, {name}!\n\nShould you find anymore--and I believe this to be an impossibility--return them to me and I shall reward you again." } })
apply(2541, { "classic" }, { deDE = { progress = "Wenn ich den Glücksbringer untersuchen kann, gelingt es mir vielleicht, die Verzauberung zu brechen. Habt Ihr einen gefunden?", completion = "Danke, {name}.\n\nWas für ein seltsamer Gegenstand das doch ist... Ich kann die üble Aura spüren, die von ihm ausgeht: eine mächtige Verzauberung." }, enUS = { progress = "If I can examine the charm, I may be able to figure out how to break the enchantment. Have you found one?", completion = "Thank you, {name}.\n\nWhat an odd trinket this is... I can sense the vile aura emanating from it; this is a very powerful enchantment." } })
apply(2561, { "classic", "forever" }, { deDE = { progress = "{name}, seid vorsichtig, wenn Ihr Euch meinem Körper nähert: Die Verzauberung, der er unterliegt, ist sehr mächtig.", completion = "Ich habe mich endlich der Kontrolle der Knarzklauen entzogen. Danke, {name}.\n\nNun kann mein Geist auf immer friedlich im Smaragdgrünen Traum verweilen.\n\nVielleicht treffen wir uns eines Tages wieder, junger Freund. Doch zunächst nehmt bitte diese Belohnung als Zeichen meiner Dankbarkeit an." }, enUS = { progress = "{name}, be wary when approaching my physical form; the enchantment it is under is quite powerful.", completion = "I am finally free of the control of the Gnarlpine. Thank you, {name}.\n\nMy spirit may now rest peacefully forever in the Emerald Dream.\n\nPerhaps one day we may meet again, young {class}. But, for now, please accept this reward as a symbol of my gratitude." } })
apply(2581, { "classic", "forever" }, { deDE = { progress = "Ihr stinkt, {name}. Habt Ihr Euch in einem Schwefelfeld herumgetrieben? Und wo sind meine Komponenten?!", completion = "Wie fühlt Ihr Euch, {name}? Ihr strahlt die Aura der Kicherfanghyänen aus - eine Kraft, die kein Sterblicher erreichen kann!\n\nLeider konnte ich mit den Komponenten, die Ihr mir gebracht habt, nur so viel von der Inhaltsstoffprobe herstellen, dass es gerade für eine Tablette reichte. Falls Ihr eine weitere Tablette benötigt, benötige ich weitere Komponenten." }, enUS = { progress = "You smell foul, {name}. Have you been traipsing in sulfur fields? And where are my components?!", completion = "How do you feel, {name}? You radiate with the aura of the snickerfang--your strength, unmatched by mortals!\n\nUnfortunately, with the components you brought to me, I could only make enough of the assay for one tablet. I will require more components, should you require another tablet." } })
apply(2582, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Organe der Bestien?", completion = "Bitte sehr... Und verwendet sie sehr sparsam. Falls Ihr noch eine brauchen solltet, dann kommt wieder zu mir, nachdem Ihr die aufgebraucht habt, die sich momentan in Eurem Besitz befindet." }, enUS = { progress = "Do you have the beast organs?", completion = "There you go! Remember, use it sparingly. If you require another, come see me after you finish the one you currently have in your possession." } })
apply(2583, { "classic", "forever" }, { deDE = { progress = "Wo sind die Organe, {name}!?", completion = "Der Geist des Ebers erleuchtet Euer Wesen, {name}! Ich frage mich, ob Ihr Euch wohl ebenso unverwundbar fühlt wie jene Bestien..." }, enUS = { progress = "Where are the organs, {name}!?", completion = "The spirit of the boar illuminates your being, {name}! I wonder, do you believe yourself to be as invulnerable as these beasts?" } })
apply(2584, { "classic", "forever" }, { deDE = { progress = "Wo sind die Organe, {name}!?", completion = "Ich muss Euch warnen, {name}. Versucht nicht, die Rezepturen, die ich geschaffen habe, miteinander zu vermischen. Die chemischen Eigenschaften des Mittels, das Ihr als Letztes eingenommen habt, werden vorherige Verzauberungen immer neutralisieren, sodass die Wirkung der vorigen Rezeptur umgehend verfliegt." }, enUS = { progress = "Where are the organs, {name}!?", completion = "I must warn you, {name}, do not attempt to mix the formulas I have created. The chemical properties of the formula you most recently ingested will always take precedence over former enchantments; thus, rendering the other formulation null." } })
apply(2585, { "classic", "forever" }, { deDE = { progress = "Wo sind die Organe, {name}!?", completion = "Faszinierend. Keine der bisher untersuchten Inhaltsstoffproben war so schwierig zu analysieren.\n\nNehmt eine Prise von dem Salz, das übrig geblieben ist, und streut es unter Eure Zunge. Ihr solltet ein leichtes Hochgefühl verspüren und anschließend einen Zustand von bislang unerreichter Beweglichkeit und Schnelligkeit erlangen." }, enUS = { progress = "Where are the organs, {name}!?", completion = "Fascinating. This has been the most difficult of all assays to analyze.\n\nTake a pinch of this residual salt and place it under your tongue. You should experience a slight feeling of euphoria followed by a state of unprecedented agility and quickness." } })
apply(2586, { "classic", "forever" }, { deDE = { progress = "Wo sind die Organe, {name}!?", completion = "Ausgezeichnete Arbeit, {name}. Hier ist eine Dosis der Inhaltsstoffprobe für Euch. Die übrigen neun werde ich für meine Forschungen nutzen.\n\nFalls Ihr mehr von der gemahlenen Skorpokinhaltsstoffprobe braucht, kommt zu mir zurück. Wir werden uns dann schon handelseinig." }, enUS = { progress = "Where are the organs, {name}!?", completion = "Fine work, {name}. Here is one sample of the assay for you and the remaining nine will be used in my research.\n\nAnytime you require more of the ground scorpok assay, return to me and we shall work out a deal." } })
apply(2601, { "classic", "forever" }, { deDE = { progress = "Habt Ihr mir die Organe gebracht, um die ich Euch gebeten hatte?", completion = "Das ist wunderbar, {name}! Mein Geschenk an Euch ist eine Kostprobe des Innenlebens des Rotsteinbasilisken.\n\nSolltet Ihr das Präparat mögen, kann ich mehr davon herstellen... gegen einen bestimmten Preis." }, enUS = { progress = "Have you returned with the requested organs?", completion = "This is wondrous, {name}! My offering to you is a taste of the inner workings of the redstone basilisk.\n\nShould the compound be to your liking, more can always be made... for a price." } })
apply(2602, { "classic", "forever" }, { deDE = { progress = "Habt Ihr mir die Organe gebracht, um die ich Euch gebeten hatte?", completion = "Ja, ja, gebt mir noch einen Moment Zeit, dann habe ich gleich wieder etwas von dem Präparat für Euch bereit, {name}.\n\nHier, bitte schön... und, {name}, versucht nicht, diese experimentellen Gebräue in zu schneller Folge zu nehmen. Das könnte katastrophale Auswirkungen haben." }, enUS = { progress = "Have you returned with the requested organs?", completion = "Yes, yes, give me a moment and more of the compound will be ready for your consumption, {name}.\n\nTake it... and {name}, do not attempt to consume these experimental concoctions in rapid succession. The results could be disastrous." } })
apply(2603, { "classic", "forever" }, { deDE = { progress = "Vergeudet meine Zeit nicht, {name}. Es gibt nichts zu besprechen, es sei denn, Ihr hättet mir die Dinge gebracht, um die ich Euch gebeten habe.", completion = "Ganz ausgezeichnet! Ich werde mich sofort an die Arbeit machen. Vielleicht lässt sich damit ein Heilmittel für viele Gebrechen auf der Welt finden!\n\nAh, ja, Eure Belohnung... solltet Ihr mehr von der Kaumasse benötigen, dann kommt wieder zu mir, und Ihr erhaltet eine weitere Aufgabe." }, enUS = { progress = "Do not waste my time, {name}. We have nothing to discuss, unless you have recovered the items I have requested.", completion = "Most excellent! I shall get to work immediately. Perhaps a cure for many of the ailments of the world is to be found!\n\nAh yes, your reward - of course, should you require more of the gum, return to me and another task you shall be given." } })
apply(2604, { "classic", "forever" }, { deDE = { progress = "Vergeudet meine Zeit nicht, {name}. Es gibt nichts zu besprechen, es sei denn, Ihr hättet mir die Dinge gebracht, um die ich Euch gebeten habe.", completion = "Vielleicht werde ich eines Tages in der Lage sein, die Enzyme zu isolieren, die den Hauptwirkstoff dieser Inhaltsstoffprobe ausmachen, und somit ein wesentlich potenteres Mittel herzustellen. Doch zunächst müsst Ihr Euch leider mit dem begnügen, was ich zurzeit zubereiten kann. Kommt wieder, falls Ihr mehr von der Muskelmagen-Kaumasse brauchen solltet." }, enUS = { progress = "Do not waste my time, {name}. We have nothing to discuss, unless you have recovered the items I have requested.", completion = "Perhaps one day I shall be able to isolate the active enzymes of this assay and produce a much more efficient resultant. Unfortunately, you will have to settle for what I am currently able to produce. Return to me should you require more gizzard gum." } })
apply(2605, { "classic", "forever" }, { deDE = { progress = "Bitte sagt mir: Habt Ihr die Tausammler gefunden?", completion = "Wie wundervoll! Gebt schon her - ich hab Durst!" }, enUS = { progress = "Please, tell me you found the dew collectors?", completion = "Oh, wonderful! Give it here -- let me drink it!" } })
apply(2606, { "classic", "forever" }, { deDE = { progress = "Der alte Marin kann's nicht lassen, was? Woraus ist dieses Gebräu gemacht?", completion = "Marin ist ein netter Kerl, versteht mich nicht falsch, nur ein bisschen... exzentrisch, würde ich sagen.\n\nUnd natürlich braucht er meine Hilfe, wie so oft." }, enUS = { progress = "So old Marin's up to it again, eh? What's this concoction made from?", completion = "Marin's a good guy, don't get me wrong -- just a little... eccentric, I'd say.\n\nAnd of course he needs my help, yet again." } })
apply(2607, { "classic", "forever" }, { deDE = { completion = "Wird auch langsam Zeit! Legt einfach den Käse auf den Tisch und verzieht Euch. Osborne wird Euch auf dem Weg nach draußen bezahlen." }, enUS = { completion = "It's about time! Just put the cheese on the table and skedaddle. Osborne will pay you on the way out." } })
apply(2621, { "classic", "forever" }, { deDE = { completion = "Thralls Zugriff... Ich erinnere mich noch ganz genau daran.\n\n<Kommandant Ruag schüttelt den Kopf.>\n\nSchreckliche Sache, was da mit diesem Regiment damals passiert ist. Die Horde verlor einige ihrer besten Soldaten, als das Bataillon vernichted wurde." }, enUS = { completion = "Thrall's Grasp... The story is still fresh in my mind.\n\n<Commander Ruag shakes his head.>\n\nTerrible thing that happened to that regiment. The horde lost some of its best soldiers when that battalion was destroyed." } })
apply(2622, { "classic", "forever" }, { deDE = { completion = "Sumpfre... red... redner..." }, enUS = { completion = "Swamp tal... talk.. talker..." } })
apply(2623, { "classic", "forever" }, { deDE = { progress = "Warten auf Befehle", completion = "Es ist schlimmer als ich dachte. Neunzehn meiner Männer hätte das entsetzliche Schicksal erspart bleiben können, das ihnen widerfahren ist. Wenn ich nur nicht so unvernünftig gehandelt hätte...\n\nIhr müsst ihnen helfen, {name}! Ich selbst kann nichts tun." }, enUS = { progress = "Awaiting orders.", completion = "It is worse than I imagined. Nineteen of my men could have been spared from the agony which they faced. If only I had not acted so irrationally.\n\nYou must help them, {name}! I am powerless to act." } })
apply(2641, { "classic", "forever" }, { deDE = { progress = "Sucht unter der Oberfläche jenes Sees; das ist der einzige Ort, wo die violetten Tragane wachsen. Ich hoffe, Ihr könnt Euren Atem lang genug anhalten!", completion = "Genau das wollte ich, {name}!\n\nDas Zeug sieht so lecker aus, dass ich am liebsten... Ha-ha, reingelegt!" }, enUS = { progress = "Under the waters of that lake -- it's the only place where the Violet Tragan can be found.  Hope you're good at holding your breath!", completion = "That's the stuff, {name}!\n\nIt looks so good, I might just...  Haha, gotcha!" } })
apply(2661, { "classic", "forever" }, { deDE = { progress = "Oh, {name}, Ihr seid endlich zurück. Was bringt Ihr mit?", completion = "Violettes Pulver, hm? Na, versuchen wir's mal - schlimmer kann es nicht mehr werden, das steht fest!" }, enUS = { progress = "Oh, {name}, you're finally back.  What have you brought?", completion = "Violet Powder, eh? Let's give it a try -- it sure couldn't make it any worse, that's for sure!" } })
apply(2662, { "classic", "forever" }, { deDE = { completion = "Trinkt das! Es ist einfach toll!!!\n\nIch wusste, ich würde es schaffen... Ach, nochmals danke für Eure Hilfe, {name}, aber bitte, tretet doch etwas zur Seite, ja? Ihr behindert meine Geschäfte! Ich werde Millionen an dem fabelhaften Noggenfogger-Elixier verdienen, Millionen!\n\nWie war das? Sprinkle sagt, ich schulde ihr was? Diese Sprinkle, immer einen Scherz auf den Lippen!" }, enUS = { completion = "Drink this! It's absolutely wonderful!!!\n\nI knew I had it in me... Oh thanks again, {name} for your help, but please, stand a little to the side, will you? You're blocking my business! I'm going to make millions on the fabulous Noggenfogger Elixir, millions!\n\nWhat's that? Sprinkle says I owe her a favor? Oh, that Sprinkle, such a kidder!" } })
apply(2681, { "classic", "forever" }, { deDE = { progress = "Die Aufgabe ist nicht leicht, {name}. Gebt nicht auf!", completion = "Ihr habt es geschafft, {name}! Die armen gequälten Seelen können endlich ruhen.\n\nDoch unsere Aufgabe ist noch nicht erfüllt, {name}. Wir haben viel zu besprechen und noch viel mehr zu erledigen." }, enUS = { progress = "It is no easy task, {name}. Do not give up!", completion = "You have done it, {name}! The poor, tortured souls can finally rest.\n\nOur work is not yet over, {name}. We have much to discuss and much more to accomplish." } })
apply(2701, { "classic", "forever" }, { deDE = { completion = "Ihr werdet von dem Glitzern und dem Strahlen darin kurzzeitig geblendet." }, enUS = { completion = "You are temporarily blinded by the sparkle and gleam." } })
apply(2702, { "classic", "forever" }, { deDE = { completion = "Ja, wirklich, Ihr habt uns allen Ehre erwiesen. Worte des Dankes allein reichen nicht aus." }, enUS = { completion = "Indeed, you have honored us all. Our thanks alone are not sufficient." } })
apply(2721, { "classic", "forever" }, { deDE = { completion = "Trebor? Trebor hat Euch geschickt?" }, enUS = { completion = "Trebor? Trebor sent you?" } })
apply(2743, { "classic", "forever" }, { deDE = { completion = "Der Dämonenlord legt eine Schläue an den Tag, die fast genauso berechnend ist wie seine Grausamkeit, {name}." }, enUS = { completion = "The demon lord displays a cunning almost as calculated as his brutality, {name}." } })
apply(2744, { "classic", "forever" }, { deDE = { progress = "Was tut Ihr hier?", completion = "Ich werde Euch helfen, obwohl ich nicht glaube, dass Euch bewusst ist, auf was Ihr Euch da eingelassen habt." }, enUS = { progress = "What are you doing here?", completion = "I will help you. Although, I do not think you fully understand what you are up against." } })
apply(2745, { "classic", "forever" }, { deDE = { completion = "Was zum...?! Schleicht Euch nicht so an mich ran! Und redet leise! Was zum Schatten, schleicht Ihr Euch so an mich ran? Seht Ihr nicht, dass ich beschäftigt bin, blöder Kerl?\n\nDämliche Frage... was werde ich hier schon tun? Ich warte darauf, dass sich das nächste Dunkle Portal öffnet, was glaubt Ihr denn, was ich mache? Also sagt, was Ihr zu sagen habt, und dann haut ab... bevor die Wachen merken, dass wir uns hier in den Büschen rumdrücken. Ich muss schließlich meinen Ruf wahren." }, enUS = { completion = "What the...?! Don't sneak up on me like that! And keep your voice down! What in the name of the Shadow are you doing sneakin' up on me for? Can't you see I'm busy, you daft fool?\n\nWhat do you mean, what am I doing? I'm waiting for the next Dark Portal to open, what the heck do you think I'm doing? Speak your peace and be off with you... 'fore the guards notice the two of us hiding in the bushes together. I have a reputation to maintain." } })
apply(2751, { "classic", "forever" }, { deDE = { progress = "Bronze, {name}! Bringt mehr Bronze!", completion = "Die Blutlinie mag vielleicht vergehen, doch die Legende der Omoshs wird weiterleben!\n\nIhr habt bewiesen, dass Ihr ein wahrer Schmied seid, {name}. Für einen Schmied ist es Belohnung genug, wenn er seine Waffen und seine Rüstungen mit dem Blut der Feinde bedeckt sieht.\n\nMögen die Brustplatten, die Ihr für zukünftige Generationen anfertigt, im Blut Eurer Feinde gebadet werden!" }, enUS = { progress = "Bronze, {name}! More bronze!!", completion = "The bloodline will fade but perhaps the legend of Omosh will continue!\n\nYou have proven that you are a blacksmith, {name}. For the blacksmith the reward is the satisfaction of seeing their weapons and armors coated in the blood of their enemies!\n\nMay the breastplates you create for the generations ahead be drenched in the blood of your enemies!" } })
apply(2752, { "classic", "forever" }, { deDE = { progress = "Zeigt mir, dass Ihr es ernst meint, {race}.", completion = "Ihr macht Orokk alle Ehre, {name}. Lest und lernt etwas über Eisenschultern!" }, enUS = { progress = "Show me your dedication, {race}.", completion = "You do Orokk proud, {name}. Read, learn of iron shoulders!" } })
apply(2753, { "classic", "forever" }, { deDE = { progress = "Ihre Schädel werden unter dem Druck Eurer Stiefel platzen!", completion = "Ihr erinnert Orokk an seinen Großvater, Häuptling Gorokk von Omosh! Lest und lernt etwas über Eisenstiefel!" }, enUS = { progress = "Their skulls will crack under the pressure of your boots!", completion = "You remind Orokk of his grandfather, Chief Gorokk of Omosh! Read, learn of the iron boot." } })
apply(2754, { "classic", "forever" }, { deDE = { progress = "Zeigt dem Eisen, wer der Herr im Hause ist, {name}!", completion = "Erstaunlich! Ihr habt die Geheimnisse der Omoshs erlernt, {name}!" }, enUS = { progress = "Show the iron who is in charge, {name}!", completion = "Astounding! You have learned the way of the Omosh, {name}!" } })
apply(2755, { "classic", "forever" }, { deDE = { completion = "<Orokk japst.>\n\nLange her, dass Orokk den Freudentanz der Omoshs getanzt hat. Lernt jetzt, {name}!" }, enUS = { completion = "<Orokk pants.>\n\nIt has been a very long time since Orokk has done the Omosh dance of joy. Learn now, {name}!" } })
apply(2756, { "classic", "forever" }, { deDE = { progress = "Wie die Zeit selbst, wartet auch Aturk auf niemanden! Beeilt Euch, Nichtsnutz!", completion = "Wie mir scheint, seid auch Ihr nichts weiter als eine selbstzufriedene Marionette des Kriegshäuptlings, {name}. Wie enttäuschend.\n\nIch sehne mich so sehr nach einem glorreichen Tod auf dem Schlachtfeld. Aber stattdessen hänge ich auf Befehl von Thrall hier fest und muss Kleinkindern beibringen, wie man Dinge herstellt! Seht zu und lernt, Kind!" }, enUS = { progress = "Aturk, like time, waits for no one! Hurry up fool!", completion = "It seems you are but another complacent lemming of the Warchief, {name}. How disappointing.\n\nHow I long for a glorious death upon the battlefield. Instead, I am stuck here, by order of Thrall, to teach infants how to craft! Watch and learn, child!" } })
apply(2757, { "classic", "forever" }, { deDE = { progress = "Eure Art is' selten, Kamerad. Zeigt mir ma' die Insignie da.", completion = "Beim Rückenhaar von Blackhoof - endlich jemand, der des Mithrilordens würdig ist!" }, enUS = { progress = "A rare breed your kind be, matey. Let me see that insignia.", completion = "By Blackhoof's back hair -- finally, one worthy of the Mithril Order!" } })
apply(2758, { "classic", "forever" }, { deDE = { progress = "Sollet Ihr vielleicht der nächste Zögling von Galvan sein?", completion = "Sehr gut, {name}! Hört zu und lernt.\n\nDie wahre Schmiedekunst entsteht niemals hier! \n\nDie wahre Schmiedekunst entsteht niemals hier! \n\nDie wahre Schmiedekunst entsteht nur hier und nirgends sonst! <Hank deutet auf sein Herz.>\n\nJetzt wisst Ihr, wo die wahre Schmiedekunst herkommt." }, enUS = { progress = "Could you be the next Galvan protege?", completion = "Very good, {name}! Listen and learn.\n\nBlacksmithing never comes from here! \n\nBlacksmithing never comes from here! \n\nBlacksmithing only comes from here! \n\nAnd now you know the origin of blacksmithing." } })
apply(2759, { "classic", "forever" }, { deDE = { progress = "Eure Art is' selten, Kamerad. Zeigt mir ma' die Insignie da.", completion = "Beim Rückenhaar von Blackhoof - endlich jemand, der des Mithrilordens würdig ist!" }, enUS = { progress = "A rare breed your kind be, matey. Let me see that insignia.", completion = "By Blackhoof's back hair -- finally, one worthy of the Mithril Order!" } })
apply(2760, { "classic", "forever" }, { deDE = { progress = "Seid gegrüßt! Kommt näher und zeigt Galvan, was Ihr da habt.", completion = "Ah, es ist schon viele Jahre her, dass jemand würdig war, in den Mithrilorden aufgenommen zu werden. Wir fangen sofort an!" }, enUS = { progress = "Hail! Come closer; show Galvan what you have.", completion = "Ah, many years it has been since one has been worthy of the Mithril Order's initiation. We will start now!" } })
apply(2761, { "classic", "forever" }, { deDE = { progress = "Nach so viel Bergbau schwellen die Muskeln an und der ganze Körper tut weh!", completion = "Ihr habt eine ausgezeichnete Arbeitsmoral, {name}! Langsam beginnt Ihr, Galvans Mineralogielehre zu verstehen! Nehmt dies und lernt alles daraus, was Ihr nur könnt." }, enUS = { progress = "After such mining, your muscles bulge and your body aches!", completion = "Your work ethic is impeccable, {name}! You are starting to understand the ways of Galvan mineralogy! Take this and learn from it all that you can." } })
apply(2762, { "classic", "forever" }, { deDE = { progress = "Nach so viel Bergbau schwellen die Muskeln an und der ganze Körper tut weh!", completion = "Es ist ein grausamer Gebieter, nicht wahr, {name}? Ich rede natürlich von Echtsilber. Jawohl, Galvan hat mehr als zehn Jahre in den Bergen von Alterac verbracht und dort diese Lektion gelernt. Nehmt dies und lernt alles daraus, was Ihr nur könnt." }, enUS = { progress = "After such mining, your muscles bulge and your body aches!", completion = "She's a cruel mistress, is she not, {name}? I'm speaking of truesilver, naturally. Aye, Galvan spent over a decade in the mountains of Alterac learning this lesson. Take this and learn from it all that you can!" } })
apply(2763, { "classic", "forever" }, { deDE = { progress = "Nach so viel Bergbau schwellen die Muskeln an und der ganze Körper tut weh!", completion = "Man kann die Augen kaum von seinem Glanz losreißen, {name}. Oh ja, der Citrin ist ein herrlicher Edelstein.\n\nPasst gut auf und lernt, was eine solche Entdeckung uns alles beibringen kann!" }, enUS = { progress = "After such mining, your muscles bulge and your body aches!", completion = "One can barely keep their eyes from leaving its splendor, {name}. Aye, citrine is a glorious gem.\n\nPay attention and learn what such a discovery may teach us!" } })
apply(2764, { "classic", "forever" }, { deDE = { completion = "Galvan der Alte hat Euch geschickt?\n\n<Trenton verneigt sich.>\n\nEs ist eine große Ehre, einen der anderen Schüler des Meisters kennen zu lernen!" }, enUS = { completion = "Galvan the Ancient sent you??\n\n<Trenton bows.>\n\nIt is a great honor to meet another of the master's pupils!" } })
apply(2765, { "classic", "forever" }, { deDE = { completion = "Es ist nur recht und billig, dass Ihr jetzt einen wesentlich mächtigeren Gegenstand erhaltet als den, den Ihr aufgabt, um hierher zu kommen. Möget Ihr immer bei guter Gesundheit sein, wenn Ihr ihn verwendet, {name}." }, enUS = { completion = "It is only fitting that you receive a trinket of far greater power than the one you sacrificed to get here. Use it in good health, {name}." } })
apply(2766, { "classic", "forever" }, { deDE = { progress = "Ihr habt anscheinend das Wrack eines... Robothuhns entdeckt... Aus dem Ei erklingt wieder die rasselnde Stimme:\n\n\"Ja, hervorragende Arbeit! Das ist tatsächlich mein Leitroboter, aber meine Sensoren zeigen an, dass er Starthilfe benötigt, bevor er zur Reparatur nach Booty Bay zurückfliegen kann. Bitte legt den Signalgeber in den Rover. Der Signalgeber wird den Rest übernehmen!\"", completion = "Ihr legt das Ei... das Notsignal... in das Huhn... den Leitroboter.\n\nAus dem Roboter ertönt ein Brummen und Surren, als er versucht aufzustehen. Nachdem der Roboter zum Leben erwacht ist, ertönt die Stimme von Oglethorpe ein weiteres Mal, diesmal aus dem Inneren des Roboters:\n\n\"OOX-22/FE funktioniert endlich, aber es sind umfangreiche Reparaturen erforderlich! Er ist zu schwer, als dass Ihr ihn tragen könntet... aber ich glaube, ich habe eine Idee. Könntet Ihr noch etwas auf ihn aufpassen?\"" }, enUS = { progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover - the beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-22/FE is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"" } })
apply(2767, { "classic", "forever" }, { deDE = { completion = "Ach, IHR habt so heldenhaft OOX-22/FE gerettet! Ich kann meine Dankbarkeit für Eure Hilfe noch nicht einmal ansatzweise ausdrücken! In meine Serie von Leitrobotern muss noch viel Entwicklungsaufwand gesteckt werden, aber Eure Bergung des Roboters hat mir zahllose Stunden zusätzlicher Schraubarbeit gespart, ganz zu schweigen von dem vielen Gold, das ich spare, weil ich ihn nicht neu bauen muss!\n\nBitte sucht Euch einen von diesen Gegenständen hier aus. Ich danke Euch nochmals für Eure großzügige Hilfe, {name}, meine Roboter und ich stehen in Eurer Schuld!" }, enUS = { completion = "Oh, YOU'RE the great savior of OOX-22/FE!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!\n\nPlease, take your choice of any of these items I have.  Thank you again for your generous assistance {name}, my robots and I are in your debt!" } })
apply(2768, { "classic", "forever" }, { deDE = { progress = "Habt Ihr Sergeant Bly gefunden? Habt Ihr meine Wünschel-mato-Rute bekommen?", completion = "Ihr habt sie gefunden! Gut gemacht, {name}! Musstet Ihr mit Bly darum kämpfen? Ich hoffe, Ihr habt ihm und seiner Bande kräftig eingeschenkt!" }, enUS = { progress = "Did you find Sergeant Bly?  Did you get my divino-matic rod?", completion = "You found it!  Well done, {name}!  Did you have to fight Bly for it?  I hope you knocked him and his band down good and hard!" } })
apply(2769, { "classic", "forever" }, { deDE = { completion = "Ihr möchtet mir also helfen? Großartig!\n\nEs gibt da so ein bestimmtes Teil, das ich für ein Experiment brauche, an dem ich gerade arbeite. Da kommt mir so ein tapferer {class} wie Ihr gerade recht. Ihr könntet es mir beschaffen!" }, enUS = { completion = "Ah, you want to help me?  Great!\n\nThere's a part I want for an experiment I'm working on, and I need a brave {class} like you to help me get it!" } })
apply(2770, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schuppe? Ich kann es kaum erwarten, die Energie darin auf unterschiedlichste Weise einzusetzen!", completion = "Toll, Ihr habt die Schuppe bekommen! Danke, {name}. Ich kann es gar nicht erwarten, endlich an die Arbeit zu gehen!\n\nIhr habt Gahz'rilla also gesehen? War er so groß, wie alle sagen?" }, enUS = { progress = "Do you have the scale?  I can't wait to try different ways to harness its energy!", completion = "Wow, you got the scale!  Thanks, {name}.  I can't wait to get to work on this thing!\n\nSo you saw Gahz'rilla?  Was he as big as they say??" } })
apply(2771, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Gegenstände schon alle angefertigt, {name}?", completion = "Ausgezeichnet! Ein fairer Tausch, wenn ich das sagen darf. Seht zu und lernt, {name}!" }, enUS = { progress = "Have you completed the crafting of the items, {name}?", completion = "Excellent! A fair tradeoff, if I do say so myself. Watch and learn, {name}!" } })
apply(2772, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Gegenstände schon alle angefertigt, {name}?", completion = "Die Welt wird Euch zu Füßen liegen, {name}! Lasst sie ruhig alle Eure Beine angreifen, kein Fußfeger kann Euch jetzt noch etwas anhaben!" }, enUS = { progress = "Have you completed the crafting of the items, {name}?", completion = "The world will be at your feet, {name}! Let them all come at your legs, for you are now unsweepable!" } })
apply(2773, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Gegenstände schon alle angefertigt, {name}?", completion = "Ich danke Euch für alles, was Ihr mich gelehrt habt, {name}. Schon bald wird der König aller verschnörkelten Mithrilrüstungsteile in Eurem Besitz sein.\n\nMerkt auf!" }, enUS = { progress = "Have you completed the crafting of the items, {name}?", completion = "Thank you for all that you have taught me, {name}. The master and commander of the ornate mithril set will soon be in your possession.\n\nBehold!" } })
apply(2781, { "classic", "forever" }, { deDE = { progress = "Ja, {class}, ich bin ein Vertreter der Gadgetzan Water Company. Was kann ich für Euch tun?", completion = "Endlich ist der Gerechtigkeit Genüge getan! Ihr habt diesen üblen Nomaden einen mächtigen Schlag versetzt! Skorpidstichs Untergang könnte entscheidend dafür sein, diese Herumtreiber endlich von Gadgetzans Wasserbrunnen zu vertreiben!\n\nIm Namen der Gadgetzan Water Company überreiche ich Euch mit Freuden dieses Kopfgeld. Ihr habt uns allen einen großen Dienst erwiesen." }, enUS = { progress = "Yes {class}, I am an official of the Gadgetzan Water Company.  What can I assist you with?", completion = "Finally - justice is served!  You have struck a mighty blow against those vile nomads!  With Scorpidsting's demise, this might be just the thing to finally push those squatters off of Gadgetzan's water wells!\n\nBy the authority of the Gadgetzan Water Company, I gladly award you with this bounty.  You've done a great service for us all." } })
apply(2782, { "classic", "forever" }, { deDE = { progress = "Ja, nun, was ist denn das?", completion = "Diese Schrifttafel... Ziemlich ungewöhnlich... Wo habt Ihr die gefunden, {name}?" }, enUS = { progress = "Well, now, what is this?", completion = "This tablet... Quite unusual... Where did you find this, {name}?" } })
apply(2783, { "classic", "forever" }, { deDE = { completion = "Die Allianz möchte helfen?\n\nIch hätte nicht gedacht, dass ich diesen Tag noch einmal erleben darf. Ein Tag, an dem die Allianz Seite an Seite mit der Horde gegen einen gemeinsamen Feind kämpft.\n\nSo soll es sein... wir werden uns verbünden." }, enUS = { completion = "The Alliance wishes to assist?\n\nI thought to never see this day again. A day in which the Alliance fights side by side with the Horde against a common enemy.\n\nIt shall be... we will unite." } })
apply(2784, { "classic", "forever" }, { deDE = { progress = "Hört, was ich zu sagen habe.", completion = "Als Geist bin ich machtlos, {name}. Unterstützt mich. Erlaubt es mir, meine Ehre wiederzuerlangen." }, enUS = { progress = "Listen to what I have to say.", completion = "As a spirit, I am powerless, {name}. Assist me. Allow me to regain my honor." } })
apply(2801, { "classic", "forever" }, { deDE = { progress = "Hört, was ich Euch zu sagen habe, {name}.", completion = "Es ist an der Zeit zu handeln, {name}." }, enUS = { progress = "Listen to what I have to say, {name}.", completion = "The time to act is now, {name}." } })
apply(2821, { "classic", "forever" }, { deDE = { progress = "Ein Zehnerstapel dicke Yetibälge bringt Euch eines meiner Handwerksstücke nach Eurer Wahl ein. Da ich auf Qualität achte, kann ich Euch versichern, dass Ihr einen guten Gegenstand erhaltet.\n\nFalls Ihr keine Yetis finden könnt, weiß ich, wo einige sein könnten. Geht von der Vergessenen Küste aus ein Stück ins Landesinnere und schaut Euch dort um, etwa auf Höhe des Wildschrammtals.", completion = "Habt Ihr Euch einmal die Zeit genommen, Euch die Beschaffenheit dieser Bälge anzusehen? Wenn man sie richtig behandelt, könnten sie tatsächlich härter sein als Eisen. Nicht viele Leute wissen von diesen Bälgen. Dazu kommt meine Kenntnis hinsichtlich verschiedener Behandlungsmethoden, die es mir erlauben wird, daraus Gegenstände mit einem echten Zeichen der Qualität herzustellen ... dank Euch natürlich!\n\nUnd jetzt sucht Euch doch bitte etwas von dem aus, was ich Euch für Euren Dienst anbieten kann!" }, enUS = { progress = "A stack of ten thick yeti hides will net you a choice of one of my crafted items.  Because I care about quality, I am able to ensure you'll get a good item!\n\nIf you can't seem to find yetis, I know where some might be.  Try looking just inland of the Forgotten Coast, around Feral Scar Vale.", completion = "Did you stop and examine the texture of these hides?  Properly treated, these hides could very well be stronger than iron.  Not many people know about these hides, and that in combination with the vast treating solutions I know will allow me to potentially make items with a true mark of quality... thanks to you, of course!\n\nAnd now, please choose from what I am able to offer you for your service!" } })
apply(2822, { "classic", "forever" }, { deDE = { progress = "Habt Ihr einen Stapel von zehn dicken Yetibälgen beschaffen können? Meine Lederwaren sind die besten und ich überlasse Euch ein solches Teil, wenn Ihr die Bälge beibringen solltet.\n\nFalls Ihr keine Yetis finden könnt, weiß ich, wo einige sein könnten. Schaut Euch im Westen um, landeinwärts von der Vergessenen Küste aus, beim Wildschrammtal.", completion = "Ah, wunderbar! Ich sage Euch, diese Bälge sind so widerstandsfähig wie Eisen, man muss ihnen nur eine besondere Behandlung zuteil werden lassen. Es wird einige Versuche kosten, die richtige Mischung zum Gerben zu finden, aber ich bin zuversichtlich, dass sie mein Zeichen der Qualität noch weiter aufwerten werden.\n\nAber nun zu Euch, {name}: Eure Hilfe hat sich als unschätzbar für mich erwiesen. Bitte sucht Euch einen der Gegenstände aus, die ich hergestellt habe." }, enUS = { progress = "Were you able to get a stack of ten thick yeti hides?  My leather goods are second to none, and I'll share a sampling with you should you have the hides.\n\nIf you can't seem to find yetis, I know where some might be.  Try looking west of here, just inland of the Forgotten Coast around the Feral Scar Vale.", completion = "Ah, excellent!  These hides, when given a special treatment, are as resilient as iron I tell you!  It will take many tries in order to get the right mix down for the tanning, but I am confident they will bring my mark of quality to the next level.\n\nAs for you, {name}... your assistance has proven invaluable to me.  Please take your choice from these items I have crafted." } })
apply(2841, { "classic", "forever" }, { deDE = { progress = "Ich sehe keine Blaupausen. Habt Ihr sie irgendwo unter Euren Kleidern versteckt oder steht Ihr hier nur rum, um mir auf die Nerven zu gehen?", completion = "Ich wusste, Ihr könnt es schaffen, {name}! Sovik wiederum hatte seine Zweifel.\n\n\n\nJetzt, da wir die Blaupausen besitzen, ist es nur noch eine Frage der Zeit, bis wir alle Gnomeninnovationen enträtselt haben, die beim Bau dieser Maschine gemacht wurden, und sie zu Goblininnovationen für unsere neuen Schreddermodelle machen können." }, enUS = { progress = "I don't see any blueprints. Did you hide them somewhere on your body or are you just standing around here to irritate me?", completion = "I knew you could do it, {name}! Sovik on the other hand, he had his doubts.\n\n\n\nNow that we have the blueprints in our possession, it is only a matter of time before we figure out all of the gnomish innovations that went into the creation of the rig and make them goblin innovations for our new shredder models." } })
apply(2842, { "classic", "forever" }, { deDE = { completion = "Ist sie nicht eine Schönheit? Ein Meisterstück der Goblin-Transporttechnologie - ist nur ein Dutzend Mal oder so explodiert.\n\nKeine Sorge, {name}, ich habe sie vollständig repariert. Sie wird Euch nicht um die Ohren fliegen - und falls doch, dann wird es schnell und schmerzlos sein." }, enUS = { completion = "She's a beauty, isn't she? Pinnacle of goblin transport technology -- only exploded a dozen or so times.\n\nDon't worry, {name}, I've got her all fixed up. She won't blow up on you - and if she does, it'll be quick and painless." } })
apply(2843, { "classic", "forever" }, { deDE = { completion = "Das war's! Wenn Ihr so weit seid, tretet einfach auf die Plattform." }, enUS = { completion = "All done! When you're ready, just step on the pad." } })
apply(2844, { "classic", "forever" }, { deDE = { completion = "Oh, ich bin ja so froh, dass Ihr mich gefunden habt! Ich muss zugeben, ich habe mich ein bisschen verlaufen... Aber ist das hier nicht ein schöner Ort?" }, enUS = { completion = "Oh, I am so glad you found me! I must admit, I am a bit lost... But isn't this a beautiful place?" } })
apply(2845, { "classic", "forever" }, { deDE = { progress = "Ich hab angefangen, mir um Euch Sorgen zu machen! Vielen Dank, dass Ihr Shay nach Hause gebracht habt, {name}.", completion = "Was? Ihr sagt, die Glocke hier hilft, wenn Shay davonläuft? Na, wenn das nichts ist!\n\nDa Ihr so viel für mich getan habt, nehmt das, {name}." }, enUS = { progress = "I was gettin' worried 'bout ya! Thank you so much for bringin' Shay home, {name}.", completion = "What? You say dis bell will work when Shay runs off? Well, how 'bout that!\n\nSince you did so much fer me, here ya go, {name}." } })
apply(2846, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Tiara, {name}? Hat Velratha den Preis dafür erfahren, sich mit mir anzulegen?", completion = "Wunderbar! Ihr habt sie gefunden! Und was genauso wichtig ist - Velratha hat sie nicht mehr! Danke, {name}. Ich stehe für immer in Eurer Schuld.\n\nUnd falls ich zuvor etwas... gemein klang, achtet nicht darauf. Ihr werdet feststellen, dass ich eine viel nettere Person denen gegenüber bin, die mich nicht bestohlen haben." }, enUS = { progress = "Do you have the tiara, {name}?  Has Velratha learned the price of crossing me?", completion = "Wonderful!  You found it!  And what's just as important--Velratha no longer has it!  Thank you, {name}.  I am forever in your debt!\n\nAnd if I sounded a little... mean before, pay it no mind.  You'll find me a much nicer person to those who haven't stolen from me." } })
apply(2847, { "classic", "forever" }, { deDE = { progress = "Wie ich schon sagte, werdet Ihr eine Weile für mich arbeiten, während Ihr alles über die Herstellung von Wildlederrüstungen lernt. Da Wildranken sowohl mächtig als auch chaotisch sind, verbessert sich die Rüstung, die Ihr herstellen werdet, auf zufällige, aber mächtige Art und Weise. Dieses Wissen war jedoch nicht einfach zu erwerben.\n\nDas Lehrgeld für diesen Prozess beträgt 10 Stücke dickes Leder.\n\nSobald das erledigt ist, kommen wir zu der Arbeit, die Ihr erledigen müsst, um die Muster zu erhalten.", completion = "Tja, {name}, es ist schön, Euch dabeizuhaben. Ihr habt als Lederer eine kluge Entscheidung getroffen; diejenigen, die Lederrüstungen verwenden, werden Euch die Bude einrennen, sobald Ihr gelernt habt, wie man Wildlederrüstungen herstellt.\n\nDann machen wir uns mal an die Arbeit... Womit wollt Ihr anfangen?" }, enUS = { progress = "Like I said, you'll be working for me while you learn about Wild Leather armor.  Because wildvines are both potent and chaotic, it yields a random but strong benefit to the already strong armor you will be making.  This knowledge, however, was not easy for me to come by.\n\nThe initial cost to begin this process is ten pieces of thick leather.\n\nOnce that is done, we'll get to the work you need to do in order to obtain the patterns.", completion = "Well {name}, I'm glad to have you on board.  You've made a smart decision as a leatherworker; those who wear leather armor will be clamoring to you once you learn how to make any of the Wild Leather armor pieces.\n\nLet's get to work - where do you want to start?" } })
apply(2848, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die 6 dicken Rüstungssets und die Wildranke, die ich benötige?\n\nSeht die Anfertigung von Rüstungssets nicht als monotone Arbeit an; der gleichmäßige Stil, den Ihr bei der Ausübung Eures Handwerks entwickelt, hilft dabei, Eure Fertigkeiten so weit zu entwickeln, dass Ihr die aufwändige Arbeit erledigen könnt, die man für die Herstellung von Wildlederrüstungen braucht.\n\nSeht, es gibt einen guten Grund für das, was Ihr für mich macht...", completion = "Diese Rüstungssets sind von robuster Qualität, {name}. Wenn es etwas gibt, das ich nicht nur von meiner Arbeit erwarte, sondern auch von der Arbeit derer, die für mich arbeiten, dann ist das Qualität.\n\nIhr habt Euch dieses Muster wohlverdient; ich hoffe, es bringt Euch dieselbe Anerkennung, die es mir gebracht hat." }, enUS = { progress = "Do you have the six thick armor kits and the wildvine I require?\n\nDon't think of making armor kits as monotonous work; the steady fashioning method you develop as you ply your trade on these kits helps develop your skills for the intricate work needed to make Wild Leather armor.\n\nSee - there's a real reason behind what you're making for me...", completion = "These armor kits are of solid quality, {name}.  If there is one thing I demand in not only my work, but the work of those in my employ, it is quality.\n\nYou've done well to earn this pattern; I hope it brings you the rewards it has brought me." } })
apply(2849, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die beiden Schildkrötenschuppenbrustplatten und -handschuhe, die ich bestellt habe? Und vergesst bitte die Wildranke nicht!\n\nSchon mit den einfachsten Mustern können wir lernen, dass sich die Grundsätze der Formen leicht auf komplexere Gewänder übertragen lassen. Auf verschiedene Weise bereitet Euch die Form der Schildkrötenschuppenbrustplatten auf den Detailreichtum vor, der für die Herstellung von Wildlederwesten benötigt wird.\n\nUnd die Handschuhe... tja, die sind nur für meinen eigenen Bedarf. Vergesst nicht, Ihr arbeitet für mich!", completion = "Das hier sind ein paar sehr schöne Stücke, {name}. Durch die Handwerkskunst und Sorgfalt, die in ihre Fertigung gesteckt wurden, werden sie einige Silbermünzen mehr einbringen als ein durchschnittlich gefertigtes Stück.\n\nIhr habt meinen Auftrag erledigt und daher erhaltet Ihr Eure Belohnung. Das Wissen um die Herstellung von Wildlederwesten ist jetzt Euer." }, enUS = { progress = "Do you have the two Turtle Scale breastplates and gloves I ordered?  Also, don't forget the wildvine!\n\nEven with the earliest patterns, we learn that the fundamentals of shape translate well into more difficult garments.  Though different items, the shape of the Turtle Scale breastplates prepares you for the detailing needed to make a Wild Leather vest.\n\nAnd the gloves... well, they're just for my own benefit.  Remember, you're working for me!", completion = "These are some very nice pieces here, {name}.  The craftsmanship and care put in to making these alone would fetch several silver more than the average piece made.\n\nYou've filled my order, and with that comes your reward.  The knowledge of making Wild Leather vests is now yours!" } })
apply(2850, { "classic", "forever" }, { deDE = { progress = "Ich muss erst diese Tuniken und Stirnbänder gefertigt sehen und benötige außerdem das Stück Wildranke, bevor ich das Wissen von den Wildlederhelmen mit Euch teilen kann.\n\nKopfbedeckungen sind unter Abenteurern sehr begehrt, sei es ein entwaffnend einfaches Stirnband oder ein Vollhelm. Die Grundlagen zur Herstellung wertvoller Kopfbedeckungen bleiben dieselben, welcher Gestalt auch immer letztendlich die Ausrüstung ist.", completion = "Diese Ausrüstung des Nachtschleichers, die Ihr geliefert habt, erfüllt den Auftrag perfekt, {name}. Ich erwarte nicht weniger von einem Lederer Eures Kalibers.\n\nIhr habt Euch dieses Muster sicherlich verdient. Ich gebe es Euch gern und hoffe, dass Ihr davon entsprechend profitieren werdet." }, enUS = { progress = "I need those tunics and headbands made, and I also need that piece of wildvine before I will share with you the knowledge of Wild Leather helmets.\n\nHead gear is highly coveted amongst adventurers, whether it be a disarmingly simple headband or a full-covering helmet.  The fundamentals of creating valued head gear remain constant, no matter what the cosmetic appearance of the gear is.", completion = "This Nightscape equipment you have supplied fills the order perfectly, {name}.  I expect no less from a leatherworker of your caliber.\n\nYou have definitely earned this pattern.  I give it to you freely, and hope you will profit from it accordingly." } })
apply(2851, { "classic", "forever" }, { deDE = { progress = "Ihr müsst erst den Auftrag betreffs der Hosen, Stiefel und Wildranken erfüllen, bevor Ihr das Muster erhaltet, {name}. Seid Ihr fertig?\n\nSchon mit den ersten Stiefeln, die man anzufertigen lernt, beginnt man zu verstehen, dass ein Qualitätsstiefel eine Gratwanderung zwischen Komfort und Funktion darstellt. Dank beider Dinge ist man in der Lage, Gegenstände herzustellen, die es dem Träger erlauben, Erschöpfungszustände zu ignorieren, die diejenigen, die Ware minderer Qualität tragen, lähmen würden.", completion = "Wieder einmal habt Ihr einen aufwändigen Auftrag mit dem Geschick einer erfahrenen Fachkraft erfüllt. Ihr habt Euch dieses Muster genauso verdient wie meinen Dank." }, enUS = { progress = "The order on the pants, boots, and wildvines needs to be filled before you get the pattern, {name}.  Are you finished?\n\nFrom the earliest pair of boots we learn how to make, we start to understand that a quality boot needs to ride a razor's edge between comfort and function.  With both, we are able to create items that allow the wearer to ignore fatigue that would cripple those wearing lower quality goods.", completion = "Once again, you've filled a complex order with the skill of a seasoned professional.  You have earned this pattern, as well as my thanks." } })
apply(2852, { "classic", "forever" }, { deDE = { progress = "Habt Ihr die Schildkrötenschuppenarmschienen und -helme fertig? Und vergesst bitte nicht die beiden Wildranken, die ich brauche!\n\nInzwischen dürftet Ihr das Potenzial der Macht zu verstehen beginnen, das in Wildlederrüstungen steckt. Eine Rüstung, deren Anwendung keine Grenzen gesetzt sind, ist unschätzbar für einen Lederer. Einschränkungen bestehen lediglich in der Rohstoffmenge, aus der man die Gegenstände herstellen kann, nicht jedoch in der Qualität der Endprodukte!", completion = "Wieder einmal habt Ihr einen Auftrag fehlerlos abgewickelt. Vielleicht komme ich eines Tages ja noch auf der Suche nach Wissen zu EUCH, hm, {name}?\n\nHier habt Ihr das Muster für die Gamaschen sowie meinen Dank. Nehmt diese Lehre in Euch auf und lasst Eure Endprodukte von Euren beeindruckenden Fähigkeiten profitieren!" }, enUS = { progress = "Do you have the Turtle Scale bracers and helms ready?  Don't forget the two wildvines I need!\n\nBy now, you're starting to realize the potential power that lies in Wild Leather armor.  An armor that has no boundaries in application is nearly invaluable to a leatherworker.  The limits are only in the quantities of resources to make the items - not the quality of the finished products!", completion = "Again, you've filled an order without flaw.  Perhaps some day I will come to YOU seeking knowledge, eh {name}?\n\nHere is the pattern for the leggings, along with my thanks.  Commit this lore to your knowledge, and let your finished products tap into your impressive skills!" } })
